    ["Convai does not show a paid plan for your key yet."] = "لا يظهر لمفتاحك باقة مدفوعة في Convai حتى الآن.",
    ["Convai free tier"] = "باقة Convai المجانية",
    ["Convai free tier: daily limit reached"] = "باقة Convai المجانية: بلغت الحد اليومي",
