    ["Conversation: {name} (archetype)"] = "المحادثة: {name} (نمط)",
    ["Conversation: {state}"] = "المحادثة: {state}",
    ["Conversations"] = "المحادثات",
    ["Conversations are disabled for this contact."] = "المحادثات معطلة لجهة الاتصال هذه.",
    ["Conversations are disabled in Companion Manager."] = "المحادثات معطلة في إدارة الرفاق.",
    ["Conversations go back to Convai free tier."] = "تعود المحادثات إلى باقة Convai المجانية.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "تستخدم المحادثات مع مفتاح Convai API المختار كمزود هذه الباقة.",
    ["Copies in party: {count}"] = "النسخ في الفريق: {count}",
    ["Copy"] = "نسخ",
    ["Copy report path"] = "نسخ مسار التقرير",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "انسخ عنوان URL الأساسي من مزودك، مثل https://openrouter.ai/api/v1، أو https://nano-gpt.com/api/v1، أو http://localhost:11434/v1 (Ollama). يقرأ من الحافظة مرة واحدة ويحفظ على هذا الحاسوب فقط.\n\nلا يسمح باستخدام http:// إلا لهذا الحاسوب وشبكتك المنزلية. يمكنك أيضا ملء endpoint= وmodel= وapi-key= في الملف player-custom-endpoint.txt داخل مجلد خدمة المحادثة.\n\nلا يرسل أي شيء حتى تختار هذا المزود أو تضغط اختبار الاتصال.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "انسخ أولا معرف النموذج من مزودك، مثل meta-llama/llama-3.1-8b-instruct على OpenRouter أو llama3.2 على Ollama. يقرأ من الحافظة مرة واحدة ويحفظ على هذا الحاسوب فقط.",
    ["Copy the report path to the clipboard so you can paste it into a message."] = "انسخ مسار التقرير إلى الحافظة لتلصقه في رسالة.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "انسخ مفتاح API الخاص بك من مزودك أولا. يقرأ من الحافظة مرة واحدة ويحفظ على هذا الحاسوب فقط، أما الخادم الموجود على حاسوبك، مثل Ollama أو LM Studio، فلا يحتاج عادة إلى مفتاح.",
    ["Copy your Mistral API key first, then press Add. It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nThe same key is the Voxtral key of the cloud voice. New Mistral accounts may not get a free API key any more."] = "انسخ مفتاح Mistral API الخاص بك أولا، ثم اضغط إضافة. يقرأ من الحافظة مرة واحدة، ويتحقق منه لدى Mistral، ويحفظ على هذا الحاسوب.\n\nهو مفتاح Voxtral نفسه الخاص بالصوت السحابي. وقد لا تحصل حسابات Mistral الجديدة على مفتاح API مجاني بعد الآن.",
    ["Copy your key first. It is read from the clipboard once, checked with Convai and saved on this computer."] = "انسخ مفتاحك أولا. يقرأ من الحافظة مرة واحدة، ويتحقق منه لدى Convai، ويحفظ على هذا الحاسوب.",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 500 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "انسخ مفتاحك من Google AI Studio أولا (aistudio.google.com/apikey، يكفي حساب Google، ولا حاجة إلى بطاقة). يقرأ من الحافظة مرة واحدة ويحفظ على هذا الحاسوب.\n\nتتيح الباقة المجانية حدا يوميا يبلغ نحو 500 رد، وهي غير متاحة في كل البلدان، وقد تستخدم Google محادثات الباقة المجانية لتحسين منتجاتها.",
    ["Copying the path needs the conversation service, which is not running. The report file is at: {path}"] = "نسخ المسار يحتاج إلى خدمة المحادثة، وهي غير قيد التشغيل. ملف التقرير موجود في: {path}",
    ["Corpo Plaza"] = "كوربو بلازا",
