    ["Downloading…"] = "جار التنزيل…",
    ["Drag the slider, or press left and right, to turn the page."] = "اسحب شريط التمرير، أو اضغط يسارا ويمينا، لتقليب الصفحة.",
    ["Dress without the fur coat"] = "فستان بدون معطف الفرو",
    ["Driver boarding"] = "السائق يصعد",
    ["Driver leaving the car"] = "السائق يغادر السيارة",
    ["Driving"] = "في الطريق",
    ["Dutch"] = "الهولندية",
    ["Dynamic info"] = "معلومات حية",
    ["ENTER  Write / Send   /   ESC  Stop typing"] = "ENTER  كتابة / إرسال   /   ESC  إنهاء الكتابة",
    ["ENTER  Write message   /   ESC  Close"] = "ENTER  كتابة رسالة   /   ESC  إغلاق",
    ["Each line also comes with vision: a recent view of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model with vision. A model without it just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "يأتي كل سطر مع الرؤية أيضا: لقطة حديثة لمحيطك، تؤخذ من نافذة اللعبة قبل لحظات من حديثك. تعمل مع كل مزود محادثة. يحتاج Local AI إلى نموذج يدعم الرؤية. النموذج الذي لا يدعمها يتلقى كلماتك فقط.\n\nنافذة اللعبة فقط، وفقط عندما يكون أحد قريبا، وتحفظ لفترة وجيزة في الذاكرة. الإيقاف يعني أنه لا يلتقط شيء.",
    ["Earlier turns kept"] = "الأدوار السابقة المحفوظة",
    ["Eddies with characters"] = "الإيدي مع الشخصيات",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with every conversation option. With Convai, your changes are sent as notes with each reply. Changes apply from the next reply."] = "عدل في متصفحك سيرة الشخصية وأسلوب كلامها وقواعد حديثها وذكرياتها، وموجه كل خيار للذكاء الاصطناعي، أو أنشئ شخصية خاصة بك.\n\nيعمل مع كل خيار محادثة. مع Convai ترسل تعديلاتك كملاحظات مع كل رد. تسري التغييرات ابتداء من الرد التالي.",
    ["Edit characters"] = "تعديل الشخصيات",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with every conversation option. With Convai, your changes are sent as notes with each reply. Changes apply from the next reply."] = "عدل في متصفحك سير الشخصيات وقواعدها وذكرياتها، وموجه كل خيار للذكاء الاصطناعي.\n\nيعمل مع كل خيار محادثة. مع Convai ترسل تعديلاتك كملاحظات مع كل رد. تسري التغييرات ابتداء من الرد التالي.",
    ["Edited"] = "تم التعديل",
    ["Empties the Search box and shows the whole list again."] = "يفرغ مربع البحث ويعرض القائمة كاملة من جديد.",
    ["End"] = "End",
    ["English"] = "الإنجليزية",
    ["Enter"] = "Enter",
    ["Error reports, developer mode and help."] = "تقارير الأخطاء، ووضع المطور، والمساعدة.",
    ["Estonian"] = "الإستونية",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "تغادر كل شخصية تسكن عندك في الوقت نفسه، من كل شقة. لا تتأثر أعضاء الفريق الذين لا يسكنون هناك. ويبقى رفيق السكن الموجود معك في فريقك.",
    ["Every named character has a bond with you, level 1 to 10. Quests finished together, a romance, eddies paid back and talking raise it; threats and insults lower it. Closer characters trust you more.\n\nA notice shows each level change. Forget clears the talk part. Off by default."] = "لكل شخصية مسماة علاقة معك، بالمستوى من 1 إلى 10. تعززها المهام المنجزة معا، والعلاقة الرومانسية، وسداد الإيدي، والحديث، بينما تضعفها التهديدات والإهانات. الشخصيات الأقرب تثق بك أكثر.\n\nيعرض إشعار كل تغيير في المستوى. ويؤدي النسيان إلى مسح جزء الحديث. متوقف افتراضيا.",
    ["Everyday people do not keep memories of your talks."] = "الأشخاص العاديون لا يحتفظون بذكريات عن أحاديثك.",
    ["Everyday people of Night City, from shopkeepers to fixers. Each joins as your own copy with their own personality."] = "أشخاص عاديون من نايت سيتي، من أصحاب المتاجر إلى الوسطاء. ينضم كل واحد منهم كنسخة خاصة بك، بشخصيته الخاصة.",
    ["Everything together is too long. Shorten something so it stays under {max} characters."] = "المجموع كله طويل جدا. اختصر شيئا حتى يبقى أقل من {max} حرفا.",
    ["Evict"] = "إخلاء السكن",
    ["Evict all housemates"] = "إخلاء السكن لجميع رفاق السكن",
    ["Example lines"] = "أمثلة على الأسطر",
    ["Example replies"] = "أمثلة على الردود",
    ["Example reply {n}"] = "مثال الرد {n}",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "تجريبي. يتحدث Pocket حتى يصبح OmniVoice جاهزا. لا يتحول الصوت المحلي أبدا إلى صوت سحابي.",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "إعدادات إضافية تضاف إلى كل رد، تكتب ككائن JSON، مثلا {example}. استخدمها لأدوات أخذ العينات التي لا يوجد لها حقل أعلاه. الإعداد الذي له حقل خاص أعلاه يرفض. إذا رفض الخادم إعدادا، يحذف، ويصل الرد مع ذلك.",
    ["Face a nearby character to talk."] = "واجه شخصية قريبة لتتحدث.",
    ["Facts the character noticed while you talked. Change or delete the ones that are wrong."] = "حقائق لاحظتها الشخصية أثناء حديثك. عدل أو احذف الخاطئة منها.",
    ["Failed"] = "فشل",
    ["Familiar face"] = "وجه مألوف",
    ["Family"] = "العائلة",
    ["Fast travel cancelled the companion trip."] = "ألغى السفر السريع رحلة الرفيق.",
    ["Favorite"] = "المفضل",
    ["Favorites"] = "المفضلة",
    ["Female"] = "أنثى",
    ["Filled in from the character you were facing: {name}."] = "تمت التعبئة من الشخصية التي كنت تواجهها: {name}.",
    ["Find the log files and save a report to share on the mod’s Discord if something goes wrong."] = "اعثر على ملفات السجل، واحفظ تقريرا لمشاركته على Discord الخاص بالمود إذا حدث خطأ ما.",
    ["Fine. Call me when you know what you want."] = "حسنا. اتصل بي عندما تعرف ما تريد.",
    ["Finish combat before asking for a ride."] = "أنه القتال قبل أن تطلب توصيلة.",
    ["Finnish"] = "الفنلندية",
    ["For Mature content"] = "للمحتوى البالغ",
    ["For a speaker with a reply length of its own"] = "لمتحدث له طول رد خاص به",
    ["For example: Character.Rebecca"] = "مثلا: Character.Rebecca",
    ["For example: Nobody in Night City knows V’s name unless V tells them. Everyone speaks casually."] = "مثلا: لا يعرف أحد في نايت سيتي اسم V إلا إذا أخبرهم بنفسه. يتحدث الجميع بعفوية.",
    ["For example: Rebecca"] = "مثلا: Rebecca",
    ["For example: V has a sister called Lena."] = "مثلا: لدى V أخت اسمها Lena.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups, writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nFailures, preparation progress and joined notices stay visible when it is off."] = "للاختبار وتقارير الأخطاء، اتركه متوقفا في اللعب العادي.\n\nيعرض النوافذ المنبثقة الاعتيادية، ويكتب سجل الحركة في مجلد التشغيل الخاص بالمود، ويسجل قرارات الإيماءات، ويضيف نفسه إلى تقارير الدعم.\n\nتبقى الأعطال وتقدم التجهيز وإشعارات الانضمام ظاهرة عندما يكون متوقفا.",
    ["Forget"] = "نسيان",
    ["Forget all memories"] = "نسيان كل الذكريات",
    ["Forget all memories ({count} characters)"] = "نسيان كل الذكريات ({count} شخصيات)",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "ينطبق نسيان كل الذكريات على هذه الشخصيات.\n\nتصفح الكتالوج أو دعوة رفيق لا يضيف أحدا إلى هذا العدد.",
    ["Forget memories"] = "نسيان الذكريات",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "نسيان الذكريات يمسح الذاكرة المعروضة هنا فقط. تبقى الذاكرة الأخرى كما هي.",
    ["Forget selected character"] = "نسيان الشخصية المحددة",
    ["Found."] = "تم العثور عليها.",
    ["Found: {list}."] = "تم العثور على: {list}.",
    ["Free"] = "مجاني",
    ["Frees about {disk} GB."] = "يحرر نحو {disk} GB.",
    ["Frees the space it took."] = "يحرر المساحة التي كان يشغلها.",
    ["French"] = "الفرنسية",
    ["Frequency penalty"] = "عقوبة التكرار",
    ["Friend"] = "صديق",
    ["Friendly"] = "ودود",
    ["From Convai, Mistral or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "من Convai أو Mistral أو Google Gemini، يؤدي تفعيله إلى اختيار Local AI، أو المخصص إذا لم يكن Local AI مثبتا. ومع Local AI يختار أيضا أكبر نموذج غير مقيد يناسب الجهاز. وإيقافه يستعيد اختياراتك.",
    ["From the content pack {name}"] = "من حزمة المحتوى {name}",
    ["From their story: {story}, from talking: {talk}"] = "من قصتهم: {story}، ومن الحديث: {talk}",
    ["From {min} to {max}."] = "من {min} إلى {max}.",
    ["GAME MODELS"] = "نماذج اللعبة",
    ["Game version"] = "إصدار اللعبة",
    ["Gamer Pro, monthly"] = "Gamer Pro، شهري",
    ["Gamer Pro, yearly"] = "Gamer Pro، سنوي",
    ["Gamer, monthly"] = "Gamer، شهري",
    ["Gamer, yearly"] = "Gamer، سنوي",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "تتذكر العصابات وNCPD والشركات وسكان كل منطقة ما فعله V: سمعة الشارع، والخيارات في المهام، والمعارك، والجرائم التي رآها الشرطة، وطريقة تعاملك مع الناس. وهذا يشكل تحيتهم وثقتهم ومساعدتهم.\n\nينطبق ذلك على الناس العاديين فقط، لا على الشخصيات المسماة أو شخصيات القصة. وهو يغير كلماتهم فقط، ولا يغير أي شيء في اللعبة.",
    ["Gender"] = "الجنس",
    ["Save report"] = "حفظ تقرير",
    ["Generated reports are saved in {path}. The five newest are kept."] = "تحفظ التقارير المنشأة في {path}، ويحتفظ بأحدث خمسة.",
    ["German"] = "الألمانية",
    ["Get your Convai API key"] = "احصل على مفتاح Convai API",
    ["Give the character a name."] = "أعط الشخصية اسما.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "العودة إلى الإعداد الأصلي للتوجيه الخاص ب {name}؟ ستحذف كل تغييراتك عليه.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "العودة إلى الإعداد الأصلي للتوجيه الخاص ب {name}؟ ستحذف تغييراتك في هذا الجزء.",
    ["Go back to the shipped text for {name}? All your changes to this character are removed."] = "العودة إلى النص الأصلي الخاص ب {name}؟ ستحذف كل تغييراتك على هذه الشخصية.",
    ["Go back to the shipped text for {name}? Your changes to this part are removed."] = "العودة إلى النص الأصلي الخاص ب {name}؟ ستحذف تغييراتك في هذا الجزء.",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "العودة إلى المظهر والحركات المعتادة الخاصة ب {name}؟ ستحذف اختياراتك في هذا الجزء.",
    ["Good friend"] = "صديق مقرب",
    ["Google Gemini (free plan)"] = "Google Gemini (مجاني)",
    ["Google Gemini API key"] = "مفتاح Google Gemini API",
    ["Google Gemini could not be reached. Check your internet connection, then try again."] = "تعذر الوصول إلى Google Gemini. تحقق من اتصالك بالإنترنت، ثم أعد المحاولة.",
    ["Google Gemini is busy right now. Try again in a moment."] = "Google Gemini مشغول الآن. أعد المحاولة بعد لحظات.",
    ["Google Gemini is not available in your region. Use Convai or Local AI."] = "Google Gemini غير متاح في منطقتك. استخدم Convai أو Local AI.",
    ["Google Gemini is rate limiting you. Wait a minute, then try again."] = "يقيد Google Gemini عدد طلباتك حاليا. انتظر دقيقة، ثم أعد المحاولة.",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "تنطق ردود Google Gemini بصوت محلي بدلا من صوت Convai السحابي.",
    ["Google Gemini: free allowance used up for today"] = "Google Gemini: انتهت الحصة المجانية لهذا اليوم",
    ["Google Gemini: key not accepted"] = "Google Gemini: المفتاح غير مقبول",
    ["Google Gemini: model unavailable"] = "Google Gemini: النموذج غير متاح",
    ["Google Gemini: not available in your region"] = "Google Gemini: غير متاح في منطقتك",
    ["Google Gemini: rate limited for a minute"] = "Google Gemini: تم تقييد الطلبات لدقيقة",
    ["Google accepted the key, but the free allowance is used up for now."] = "قبلت Google المفتاح، لكن الحصة المجانية انتهت حاليا.",
    ["Google accepted the key."] = "قبلت Google المفتاح.",
    ["Google did not accept this key. Check it in Google AI Studio, then Remove it and Add the right one."] = "لم تقبل Google هذا المفتاح. تحقق منه في Google AI Studio، ثم اضغط إزالة وأدخل المفتاح الصحيح بالضغط على إضافة.",
    ["Google did not accept your Gemini key. Check it in Google AI Studio and add it again."] = "لم تقبل Google مفتاح Gemini الخاص بك. تحقق منه في Google AI Studio وأضفه مرة أخرى.",
    ["Graphics card"] = "بطاقة الرسوميات",
    ["Greek"] = "اليونانية",
    ["Group chat needs two characters nearby. Use {key} for one person."] = "تحتاج الدردشة الجماعية إلى شخصيتين قريبتين. استخدم {key} لمحادثة شخص واحد.",
    ["Group text chat"] = "دردشة نصية جماعية",
    ["Group voice chat"] = "دردشة صوتية جماعية",
    ["Heading of the character’s own right-now facts"] = "عنوان الحقائق الآنية الخاصة بالشخصية",
    ["Heading of the example replies"] = "عنوان الردود النموذجية",
    ["Heading of the format notes"] = "عنوان ملاحظات التنسيق",
    ["Heading of the notes for this turn"] = "عنوان ملاحظات هذه الجولة",
    ["Heading of the output rules"] = "عنوان قواعد المخرجات",
    ["Heading of the right-now facts"] = "عنوان الحقائق الآنية",
    ["Heading of the things remembered about V"] = "عنوان الأشياء المتذكرة عن V",
    ["Heading of the world and quest context"] = "عنوان سياق العالم والمهام",
    ["Heading of what the character remembers"] = "عنوان ما تتذكره الشخصية",
    ["Health, heat and fights"] = "الصحة والمطاردة والمعارك",
    ["Hebrew"] = "العبرية",
    ["Help and support"] = "المساعدة والدعم",
    ["Heywood Glen"] = "هايوود غلين",
    ["Highest level"] = "أعلى مستوى",
    ["Hindi"] = "الهندية",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "امسك Shift أو Ctrl أو Alt أثناء الضغط على مفتاح لتعيين تركيبة مثل Shift+F5. لا تعمل التركيبة إلا عند الإبقاء على هذه المفاتيح بالضبط، ولا يعمل المفتاح المفرد أثناء الإبقاء على أحدها. في اللعبة، يستخدم Shift للركض، وCtrl للتفادي، وAlt لفتح عجلة السلاح، لذلك يفعل V الشيء نفسه أيضا.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "اضغط مطولا للتحدث إلى جوني سيلفرهاند، الصوت الذي في رأسك، أينما توجهت، وارفع إصبعك للإرسال. يحتاج ذلك إلى تفعيل جوني في رأسك من الإعدادات.",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "اضغط مطولا للتحدث مع كل الشخصيات من حولك دفعة واحدة، وارفع إصبعك للإرسال. إن لم تواجه أحدا، ستتحدث إلى أول عضو في مجموعتك واثنين آخرين منها.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "اضغط الزر أو المفتاح مطولا أثناء الكلام وارفع إصبعك للإرسال، تماما كمفتاح الكلام في Cyber Engine Tweaks. إن لم تواجه أحدا، ستتحدث إلى أول عضو في مجموعتك.",
    ["Holocall ended: combat started."] = "انتهت المكالمة الهولوغرافية: بدأ القتال.",
    ["Holocall with {name} ended."] = "انتهت المكالمة الهولوغرافية مع {name}.",
    ["Home"] = "Home",
    ["Home clothes: shirt and trousers"] = "ملابس المنزل: قميص وبنطال",
    ["Home clothes: t-shirt and trousers"] = "ملابس المنزل: تي شيرت وبنطال",
    ["Home clothes: tank top and trousers"] = "ملابس المنزل: فانيلة وبنطال",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "ملابس المنزل: فانيلة وشورت وشبشب",
    ["Hooded jacket"] = "جاكيت بقلنسوة",
    ["Housemates"] = "رفاق السكن",
    ["Housemates in one chat"] = "رفاق السكن في دردشة واحدة",
    ["Housemates moved out: {count}"] = "غادر رفاق السكن: {count}",
    ["Housemates talk to each other"] = "يتحدث رفاق السكن مع بعضهم",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "حالة V وفق المودات الأخرى عند تثبيتها، مثل التعب والجوع والعطش والأعصاب والإدمانات من Dark Future على سبيل المثال. وكذلك ما يرتديه V ظاهرا أثناء تفعيل زي من Equipment-EX، فتصف الشخصيات الزي لا الملابس التي يخفيها.\n\nمتوقف افتراضيا. عند الإيقاف لا يرسل شيء، ولا يقرأ أي شيء من تلك المودات.",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "كيف يطلب من كل خيار محادثة أن يجيب. لكل خيار توجيهه الخاص. يسري التغيير من الرد التالي، ولا يلزم إعادة تشغيل أي شيء.",
    ["How everyone sounds, and how you talk."] = "كيف يبدو صوت الجميع، وكيف تتحدث.",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "مدى حرية النموذج في صياغة رده. اترك الخانة فارغة لاستخدام القيمة الأصلية.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "المدة منذ آخر مرة تحدث فيها V مع هذه الشخصية، داخل اللعبة وبالأيام الحقيقية: منذ الليلة الماضية، أو منذ أيام. تذكر فقط عندما تكون الفجوة طويلة بما يكفي لتكون مهمة، ولا تذكر مرة أخرى في المحادثة نفسها.\n\nعند الإيقاف لا يرسل شيء، ويتوقف المود عن قراءة ساعة اللعبة لهذا الغرض.",
    ["How long she waits"] = "مدة انتظارها",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "مدة انتظارها لك بعد وصولها الآن. بعد وصول مجدول تنتظر بقدر التأخير الذي اخترته. يتوقف الانتظار أثناء وجودك في قتال أو مشهد أو قائمة.",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "المدة التي يبقى فيها رفاق السكن هادئين بعد دردشة قبل أن يبدؤوا أخرى. ولا يزال إعداد «تحدث الرفاق» يحدد عدد الدردشات التي تصل في الساعة.",
    ["How loud V’s own voice is, for V’s typed and microphone lines. 100 is the normal level, 150 the default.\n\nAbove 100 the voice gets louder, with a limiter so it does not crackle. The companions’ voices and the game’s own dialogue and sounds do not change.\n\nThe next line uses it."] = "مستوى صوت V نفسه، للأسطر المكتوبة وأسطر الميكروفون. المستوى العادي 100، والافتراضي 150.\n\nفوق 100 يصبح الصوت أعلى، مع محدد لمنع التشويش. لا تتغير أصوات الرفاق وحوار اللعبة وأصواتها.\n\nيستخدم السطر التالي هذا المستوى.",
    ["How loud the companions’ and characters’ voices are. 100 is the normal level, 150 the default.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. V’s voice has its own setting below, and the game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "مستوى صوت الرفاق والشخصيات. المستوى العادي 100، والافتراضي 150.\n\nفوق 100 تصبح الأصوات أعلى، مع محدد لمنع التشويش. لصوت V إعداد خاص أدناه، ولا تتغير حوارات اللعبة وأصواتها.\n\nيستخدم الرد التالي هذا المستوى.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "عدد رفاق السكن الذين ينضمون إلى دردشة واحدة عندما يكون هذا العدد في المنزل قريبين من بعضهم. يتحدثون واحدا تلو الآخر. وعند وجود عدد أقل في المنزل، تكون الدردشة بأكبر حجم ممكن.",
    ["How she arrives"] = "طريقة وصولها",
    ["How the game finds this character"] = "كيف تجد اللعبة هذه الشخصية",
    ["How the hands move while they speak a longer reply."] = "كيف تتحرك اليدان أثناء النطق برد أطول.",
    ["How they sound: pace, attitude, favourite habits of speech."] = "كيف تبدو أصواتهم: الإيقاع والنبرة والعادات الكلامية المفضلة.",
    ["Hungarian"] = "المجرية",
    ["Hurt: {points}"] = "مجروح: {points}",
    ["Hurt: {points}, gone in about a game day"] = "مجروح: {points}، يزول خلال يوم تقريبا في اللعبة",
    ["Hurt: {points}, gone in about {days} game days"] = "مجروح: {points}، يزول خلال نحو {days} من أيام اللعبة",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "انتظرتك {minutes} دقيقة في {place} ولم تحضر أبدا. انس الأمر.",
    ["I'm here at {place}. Where are you?"] = "أنا هنا في {place}. أين أنت؟",
    ["INVITE QUEUED - CLOSE PHONE"] = "الدعوة في قائمة الانتظار: أغلق الهاتف",
    ["Idle moves"] = "حركات الخمول",
    ["If a character stops answering, voices stop or an error appears: choose Save report and share the file it names on the mod’s Discord (https://discord.gg/p4pxQhAvJ), with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "إذا توقفت شخصية عن الرد، أو انقطعت الأصوات، أو ظهر خطأ: اختر حفظ تقرير، وشارك الملف الذي يسميه على Discord الخاص بالمود (https://discord.gg/p4pxQhAvJ)، مع ملاحظة قصيرة عما كنت تفعله.\n\nتوضح السجلات المذكورة أدناه ما الذي سار بشكل خاطئ.",
    ["If something goes wrong"] = "عند حدوث مشكلة",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "إذا كان المجلد موجودا، يوضح أحدث سجل في red4ext/logs سبب عدم تحميل RED4ext له: إما مضاد فيروسات أزال ملفا، أو Visual C++ Runtime مفقود.",
    ["Immersive invitations"] = "دعوات غامرة",
    ["In 10 minutes"] = "خلال 10 دقائق",
    ["In 2 minutes"] = "خلال دقيقتين",
    ["In 5 minutes"] = "خلال 5 دقائق",
    ["In front of you"] = "أمامك",
    ["In person"] = "وجها لوجه",
    ["In use now"] = "قيد الاستخدام حاليا",
    ["In your party: {count}"] = "في مجموعتك: {count}",
    ["Indonesian"] = "الإندونيسية",
    ["Insert"] = "Insert",
    ["Install"] = "تثبيت",
    ["Install or update: {names}. Then restart the game."] = "ثبت أو حدث: {names}. ثم أعد تشغيل اللعبة.",
    ["Installed"] = "مثبت",
    ["Installed character models"] = "نماذج الشخصيات المثبتة",
    ["Installed. OmniVoice uses it when it starts."] = "تم التثبيت. يستخدمه OmniVoice عند بدء التشغيل.",
    ["Interface"] = "الواجهة",
    ["Interface language"] = "لغة الواجهة",
    ["Internet"] = "الإنترنت",
    ["Invalid Mature content settings."] = "إعدادات المحتوى للبالغين غير صالحة.",
    ["Invalid conversation settings."] = "إعدادات المحادثة غير صالحة.",
    ["Invite"] = "دعوة",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "ادع رفيقا وستأتيك فعلا: تظهر خارج الأنظار، وتمشي أو تقود نحوك، وتراسلك حين تصل، وتنتظرك.",
    ["Invite someone from Characters or Model browser."] = "ادع أحدا من الشخصيات أو من متصفح النماذج.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "تجهز الشخصيات المدعوة فورا. تبدأ ذاكرتهم عندما تتحدث معهم فعلا.\n\nتشارك هوية لاعب واحدة بين جميع ملفات الحفظ وتبقى كما هي بعد النسيان.\n\nيصف سياق اللعبة الحالي العالم الذي حملته.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "تدعو شخصيات هذه المجموعة إلى جانبك: {names}.\n\nتضاف إلى مجموعتك ولا تصرف أي شخصية. لا تدعى الشخصية التي معك بالفعل مرتين. ويذكر كل من لا يستطيع الحضور مع السبب.",
    ["Inviting characters and managing your party need a loaded game."] = "دعوة الشخصيات وإدارة مجموعتك تتطلب لعبة محملة.",
    ["Inworld API key"] = "مفتاح Inworld API",
    ["Inworld cloud voice"] = "صوت Inworld السحابي",
    ["Inworld did not accept that key."] = "لم يقبل Inworld ذلك المفتاح.",
    ["Inworld is not used with Mature content."] = "لا يستخدم Inworld مع المحتوى للبالغين.",
    ["Inworld · Cloud voice"] = "Inworld · صوت سحابي",
    ["Inworld · needs key"] = "Inworld · يحتاج مفتاحا",
    ["Inworld · not with Mature"] = "Inworld · لا مع البالغين",
    ["Inworld · Expressive"] = "Inworld · تعبيري",
    ["Expressive · needs key"] = "تعبيري · يحتاج مفتاحا",
    ["Expressive · not with Mature"] = "تعبيري · لا مع البالغين",
    ["Inworld: cloud voices with your own Inworld key. Expressive follows the tone each character writes, but it starts speaking a little later than plain Inworld."] = "Inworld: أصوات سحابية بمفتاح Inworld الخاص بك. الصوت التعبيري يتبع النبرة التي تكتبها كل شخصية، لكنه يبدأ الكلام متأخرا قليلا عن Inworld العادي.",
    ["It also stops everyone the game builds from the same record, so other people of the same kind may stop answering too."] = "كما يوقف كل من تنشئه اللعبة من السجل نفسه، لذا قد يتوقف الآخرون من النوع نفسه عن الرد أيضا.",
    ["It answered in {ms} ms."] = "أجاب خلال {ms} ms.",
    ["It answers in {ms} ms."] = "يجيب خلال {ms} ms.",
    ["It could not be saved."] = "تعذر الحفظ.",
    ["It is kept in the mod’s data folder on drive C:."] = "يحفظ في مجلد بيانات المود على القرص C:.",
    ["It picks the voice when the character has no clip."] = "يختار الجنس الصوت عندما لا يتوفر للشخصية مقطع.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "يعمل في الخلفية أثناء اللعب. تستمر اللعبة في العمل، ولا يتغير أي شيء آخر.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "يشغل نحو {disk} GB على القرص C: في مجلد بيانات المود.",
    ["Italian"] = "الإيطالية",
    ["Its voice runs on {device}."] = "يعمل صوته على {device}.",
    ["Japanese"] = "اليابانية",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "يرد جوني سيلفرهاند على مفاتيح «التحدث إلى جوني» بوصفه الصوت في رأس V، بمجرد أن تضعه القصة هناك. عين مفتاحا ل«التحدث إلى جوني» في صفحة تعيين المفاتيح، إذ لا يوجد مفتاح محدد افتراضيا.\n\nتشغيل: يجيب عندما تتحدث إليه. نادرا: يبادر بالكلام من تلقاء نفسه، نحو مرتين في الساعة. عادي: نحو 4. غالبا: نحو 6.\n\nوإذا تحدث الرفاق أيضا، تتراكم المعدلات ويتناوبون على الكلام.",
    ["Johnny in your head"] = "جوني في رأسك",
    ["Joining..."] = "جاري الانضمام...",
    ["Keep at least one rule."] = "احتفظ بقاعدة واحدة على الأقل.",
    ["Keep memories"] = "الاحتفاظ بالذكريات",
    ["Keep this copy without a conversation identity"] = "احتفظ بالنسخة دون هوية محادثة",
    ["Kept until forgotten"] = "محفوظة حتى يتم نسيانها",
    ["Key bindings"] = "تعيين المفاتيح",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "يحتاج تعيين المفاتيح إلى Codeware، وهذه اللعبة لا تملكه. افتح المساعدة لمعرفة ما هو ناقص.",
    ["Key or button"] = "مفتاح أو زر",
    ["Korean"] = "الكورية",
    ["Last report"] = "آخر تقرير",
    ["Last talked: today"] = "آخر حديث: اليوم",
    ["Last talked: yesterday"] = "آخر حديث: أمس",
    ["Last talked: {days} days ago"] = "آخر حديث: قبل {days} أيام",
    ["Latvian"] = "اللاتفية",
    ["Launcher log"] = "سجل المشغل",
    ["Layout"] = "التخطيط",
    ["Leave a version empty to use the rule text."] = "اترك الصيغة فارغة لاستخدام نص القاعدة.",
    ["Left arrow"] = "السهم الأيسر",
    ["Length limits"] = "حدود الطول",
    ["Level {level}"] = "المستوى {level}",
    ["Lines in their voice. They show the tone only and are never said back word for word."] = "أسطر بصوتهم. تظهر النبرة فقط، ولا تعاد أبدا كلمة بكلمة.",
    ["Lip sync delay (Bluetooth)"] = "تأخير مزامنة الشفاه (Bluetooth)",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite وStandard هما حجما نموذج Local AI. يستخدم «للبالغين مفعل» طالما المحتوى للبالغين مفعل.",
    ["Lithuanian"] = "اللتوانية",
    ["Live picture unavailable. The call continues with the portrait."] = "الصورة المباشرة غير متاحة. تستمر المكالمة بالصورة الشخصية.",
    ["Lively: bigger gestures, more often"] = "حيوية: إيماءات أكبر وأكثر",
    ["Load a save before inviting a companion."] = "حمل ملف حفظ قبل دعوة رفيق.",
    ["Load a save first"] = "حمل ملف حفظ أولا",
    ["Load a save first. A key can be set only while a game is loaded."] = "حمل ملف حفظ أولا. لا يمكن تعيين مفتاح إلا أثناء تحميل لعبة.",
    ["Loaded."] = "تم التحميل.",
    ["Loading"] = "جاري التحميل",
    ["Loading the OmniVoice voice…"] = "جاري تحميل صوت OmniVoice…",
    ["Loading the Pocket voice…"] = "جاري تحميل صوت Pocket…",
    ["Loading..."] = "جاري التحميل...",
    ["Local AI"] = "Local AI",
    ["Local AI could not answer that. Try again in a moment."] = "تعذر على Local AI الرد على ذلك. أعد المحاولة بعد لحظات.",
    ["Local AI could not start. Save a report below and share it on the mod’s Discord, or choose another conversation provider."] = "تعذر تشغيل Local AI. احفظ تقريرا أدناه وشاركه على Discord الخاص بالمود، أو اختر مزود محادثة آخر.",
    ["Local AI did not answer within {seconds} s. Try again, or choose a smaller model in Settings."] = "لم يجب Local AI خلال {seconds} s. أعد المحاولة، أو اختر نموذجا أصغر من الإعدادات.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "لم يجد Local AI بطاقة رسوميات يمكنه استخدامها. يحتاج إلى بطاقة NVIDIA أو AMD مع أحدث برنامج تشغيل. حدث برنامج التشغيل، أو اختر مزود محادثة آخر.",
    ["Local AI is back on your graphics card, so replies are faster again."] = "عاد Local AI إلى بطاقة الرسوميات لديك، لذلك أصبحت الردود أسرع مجددا.",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "يبقي Local AI على {model} كما سمحت، مع جزء منه في ذاكرة النظام. ستكون الردود أبطأ.",
    ["Local AI is not ready, so Convai took that message and did not answer in time."] = "Local AI غير جاهز، لذلك تلقى Convai تلك الرسالة ولم يجب في الوقت المناسب.",
    ["Local AI is ready."] = "Local AI جاهز.",
    ["Local AI is still loading its model. Try again in a moment."] = "Local AI ما زال يحمل نموذجه. أعد المحاولة بعد لحظات.",
    ["Local AI is warming up…"] = "جاري تجهيز Local AI…",
    ["Local AI model"] = "نموذج Local AI",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "يعمل Local AI هنا في الغالب على المعالج لديك، لذلك ستكون الردود بطيئة.",
    ["Local AI stopped working and was restarted."] = "توقف Local AI عن العمل وأعيد تشغيله.",
    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "تحول Local AI إلى {model}: تستخدم اللعبة معظم ذاكرة الرسوميات لديك.",
    ["Local AI, Lite"] = "Local AI، Lite",
    ["Local AI, Lite, Mature on"] = "Local AI، Lite، للبالغين مفعل",
    ["Local AI, Standard"] = "Local AI، Standard",
    ["Local AI, Standard, Mature on"] = "Local AI، Standard، للبالغين مفعل",
    ["Location"] = "الموقع",
