    ["Name"] = "الاسم",
    ["Natural speech"] = "الكلام الطبيعي",
    ["Natural speech needs a local voice, so {setting} was switched to {voice}."] = "يحتاج الكلام الطبيعي إلى صوت محلي، لذا تم تغيير {setting} إلى {voice}.",
    ["Needs Local AI or Custom."] = "يحتاج إلى Local AI أو المخصص.",
    ["Needs a browser"] = "يحتاج إلى متصفح",
    ["Needs your own Inworld key, from inworld.ai. Inworld’s free plan is a one-time trial of about 70 minutes of speech, then you pay as you go.\n\nCopy your key first, then press Add. It is read from the clipboard once, checked with Inworld and saved on this computer."] = "يحتاج إلى مفتاح Inworld خاص بك من inworld.ai. الخطة المجانية ل Inworld نسخة تجريبية لمرة واحدة تضم نحو 70 دقيقة من الكلام، ثم تدفع حسب الاستخدام.\n\nانسخ مفتاحك أولا، ثم اضغط إضافة. تقرأ الحافظة المفتاح مرة واحدة، وتتحقق منه لدى Inworld، وتحفظه على هذا الكمبيوتر.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "ممنوع دائما: الجنس مع القاصرين أو دون موافقة، والجنس عن أشخاص حقيقيين، والكراهية، وتعليمات الأسلحة أو المخدرات الواقعية. يفرض فحص الأمان قاعدة القاصرين.",
    ["New address saved. Paste your API key again for it."] = "تم حفظ العنوان الجديد. الصق مفتاح API له من جديد.",
    ["New character"] = "شخصية جديدة",
    ["Next page"] = "الصفحة التالية",
    ["Night City"] = "نايت سيتي",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "لم يحفظ بعد أي مفتاح API. انسخ مفتاحك من مزودك، واضغط لصق مفتاح API، ثم اختبر من جديد.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "لا توجد حزمة Local AI. نزل واحدة من صفحة المود على Hugging Face واستخرجها في مجلد Cyberpunk 2077، أو اختر مزود محادثة آخر.",
    ["No clear, reachable companion space on this floor. Move to a wider spot and try again."] = "لا توجد مساحة واضحة يمكن الوصول إليها لرفيق في هذا الطابق. انتقل إلى مكان أوسع وحاول من جديد.",
    ["No clip yet."] = "لا يوجد مقطع بعد.",
    ["No closing line."] = "لا توجد جملة ختامية.",
    ["No conversation profile. This model joins as a follower without AI conversations."] = "لا يوجد ملف محادثة. ينضم هذا النموذج كتابع دون محادثات بالذكاء الاصطناعي.",
    ["No entries are available."] = "لا توجد عناصر متاحة.",
    ["No entries yet.\nTry another search or tab."] = "لا توجد عناصر بعد.\nجرب بحثا آخر أو تبويبا آخر.",
    ["No example replies."] = "لا توجد أمثلة للردود.",
    ["No jacket"] = "بدون سترة",
    ["No jacket and harness"] = "بدون سترة ومع الحزام",
    ["No key added"] = "لم تتم إضافة مفتاح",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "لم يصل أي ضغط مفتاح إلى المود، لذا لم يتغير شيء. إذا لم تصل المفاتيح من هذه القائمة، فعين المفتاح في Bindings الخاص ب Cyber Engine Tweaks، فهو يعمل بالطريقة نفسها.",
    ["No key was pressed, so nothing changed."] = "لم يضغط أحد أي مفتاح، لذا لم يتغير شيء.",
    ["No match."] = "لا يوجد تطابق.",
    ["No matches. Try another name or clear the search."] = "لا توجد نتائج. جرب اسما آخر أو امسح البحث.",
    ["No model installed"] = "لا يوجد نموذج مثبت",
    ["No option matched. Say its number."] = "لم يتطابق أي خيار. قل رقمه.",
    ["No problem found. Select a line to see what was checked."] = "لا توجد مشكلة. اختر سطرا لترى ما الذي تم فحصه.",
    ["No reply arrived within {seconds} s. Try again."] = "لم يصل رد خلال {seconds} ثانية. حاول من جديد.",
    ["No reply arrived. The conversation service may not be running."] = "لم يصل رد. ربما لا تعمل خدمة المحادثة.",
    ["No reply received. Your message is in the draft; press Enter to retry."] = "لم يصل رد. رسالتك موجودة في المسودة، اضغط Enter لإعادة المحاولة.",
    ["No settings were supplied."] = "لم يتم إرسال أي إعدادات.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the full install zip (AI-Companions-LLM) straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The full install is on the mod’s Nexus Mods page."] = "لا أثر لخدمة المحادثة في هذه الجلسة: Runtime مفقود أو لم يتم تحميله. استخرج ملف التثبيت الكامل (AI-Companions-LLM) مباشرة في مجلد Cyberpunk 2077 (لا في مجلد جديد)، وتحقق من وجود red4ext/plugins/AiNpcCyberpunkMod، ثم أعد تشغيل اللعبة. التثبيت الكامل متاح في صفحة المود على Nexus Mods.",
    ["No speech was heard. Hold the talk key while you speak."] = "لا يوجد كلام مسموع. اضغط مفتاح التحدث مع الاستمرار أثناء كلامك.",
    ["No story yet"] = "لا توجد قصة بعد",
    ["Nobody lives at your place."] = "لا أحد يسكن في مكانك.",
    ["Nobody yet"] = "لا أحد بعد",
    ["Nod while you talk to them"] = "الإيماء أثناء الحديث معهم",
    ["None found: installed by hand."] = "لا يوجد شيء: مثبت يدويا.",
    ["None installed. They are optional."] = "لا يوجد شيء مثبت. هي اختيارية.",
    ["None yet"] = "لا شيء بعد",
    ["None: the hands stay at rest"] = "لا شيء: تبقى اليدان ساكنتين",
    ["None: they keep the stance they have"] = "لا شيء: يحتفظون بوضعيتهم الحالية",
    ["Normal"] = "عادي",
    ["Normal memory"] = "ذاكرة عادية",
    ["Norwegian"] = "النرويجية",
    ["Not added"] = "غير مضاف",
    ["Not available"] = "غير متاح",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "غير متاح على هذا الكمبيوتر. يحتاج إلى بطاقة AMD Radeon وحزمة OmniVoice.",
    ["Not available right now."] = "غير متاح حاليا.",
    ["Not checked yet"] = "لم يتم فحصه بعد",
    ["Not connected. Replies show as text until the server answers."] = "غير متصل. تظهر الردود نصا حتى يرد الخادم.",
    ["Not enough free graphics memory to start Local AI. Try a smaller model in Settings."] = "ذاكرة الرسوميات الحرة غير كافية لتشغيل Local AI. جرب نموذجا أصغر في الإعدادات.",
    ["Not enough free system memory to start Local AI. Close other programs, try a smaller model in Settings, or use the Custom provider."] = "ذاكرة النظام الحرة غير كافية لتشغيل Local AI. أغلق البرامج الأخرى، أو جرب نموذجا أصغر في الإعدادات، أو استخدم المزود المخصص.",
    ["Not enough memory"] = "ذاكرة غير كافية",
    ["Not needed: Local AI and the voice run on this PC."] = "غير مطلوب: يعمل Local AI والصوت على هذا الكمبيوتر.",
    ["Not running"] = "لا يعمل",
    ["Not set"] = "غير معين",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "غير قابل للاستخدام: {models}. راجع ملاحظات Local AI، «إضافة نموذجك الخاص».",
    ["Not used"] = "غير مستخدم",
    ["Note"] = "ملاحظة",
    ["Notes for this turn"] = "ملاحظات لهذه الجولة",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "لم يرد أي شيء على هذا العنوان. تحقق من أن الخادم يعمل، ومن صحة العنوان والمنفذ، ومن أن الكمبيوترين على الشبكة نفسها. الخادم الذي يبدأ بإعداداته الافتراضية يستمع إلى كمبيوتره فقط: شغله بعنوان الاستماع 0.0.0.0.",
    ["Nothing yet."] = "لا شيء بعد.",
    ["Nothing you use now depends on it."] = "لا شيء تستخدمه الآن يعتمد عليه.",
    ["Num lock"] = "Num Lock",
    ["OK"] = "OK",
    ["Off"] = "إيقاف",
    ["Off. OmniVoice runs on this PC."] = "إيقاف. يعمل OmniVoice على هذا الكمبيوتر.",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "إيقاف: الدعوة تحضر الرفيق إلى جانبك فورا.\n\nتشغيل: الرفيق الذي تدعوه، عبر زر الدعوة أو تبويب جهات الاتصال أو رسالة، يصل إليك بعد الوقت الذي تختاره هنا. ترسل لك رسالة حين تصل، وتنتظر، وتغادر غاضبة (وتتذكر ذلك) إذا لم تأت أبدا.",
    ["Off: V is silent.\n\nTyped lines: the lines you type are spoken out loud too, in the V voice that matches yours, then the companion answers.\n\nTyped and spoken lines: what you say by microphone (hold to talk or Voice activation) is also spoken by V, and the reply follows V’s line.\n\nV’s line is always waited for, up to about 30 s without audio. The next row picks the voice engine."] = "إيقاف: V صامت.\n\nالأسطر المكتوبة: الأسطر التي تكتبها تنطق بصوت عال أيضا، بصوت V الذي يناسب صوتك، ثم يجيب الرفيق.\n\nالأسطر المكتوبة والمنطوقة: ما تقوله عبر الميكروفون (اضغط للتحدث أو تفعيل الصوت) ينطق أيضا بصوت V، ويأتي الرد بعد سطر V.\n\nينتظر سطر V دائما، حتى نحو 30 ثانية دون صوت. يختار الصف التالي محرك الصوت.",
    ["Off: no subtitles.\n\nCinematic subtitles: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nWith Companion voices Off as well, automatic reactions stay silent."] = "إيقاف: بدون ترجمة نصية.\n\nترجمة سينمائية: ترجمة الحوار العادية في اللعبة.\n\nفوق المتحدث: فوق الرفيق الذي يتكلم.\n\nومع إيقاف أصوات الرفاق أيضا، تبقى الردود التلقائية صامتة.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "إيقاف: الردود نصية فقط، ولا يتم توليد أي صوت.\n\nومع إيقاف الترجمة النصية أيضا، تبقى الردود التلقائية صامتة.",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "إيقاف: إذا لم يتسع نموذج Local AI الذي اخترته في ذاكرة الرسوميات الحرة إلى جانب اللعبة، يتم تحميل نموذج أصغر يتسع له بدلا منه، مع إشعار واحد.\n\nتشغيل: يبقى النموذج الذي اخترته، ويعمل جزء منه من ذاكرة النظام (RAM) على المعالج. تكون الردود أبطأ، ويتم إبلاغك بذلك مرة واحدة. يحتاج إلى ذاكرة RAM حرة كافية، وقد تحصل اللعبة على وقت معالج أقل.",
    ["OmniVoice"] = "OmniVoice",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice could not load. See Help in Settings."] = "تعذر تحميل OmniVoice. راجع المساعدة في الإعدادات.",
    ["OmniVoice for AMD"] = "OmniVoice لبطاقات AMD",
    ["OmniVoice needs 12 GB"] = "يحتاج OmniVoice إلى 12 GB",
    ["OmniVoice needs NVIDIA"] = "يحتاج OmniVoice إلى NVIDIA",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "يحتاج OmniVoice إلى بطاقة رسوميات NVIDIA، ولا توجد بطاقة صالحة للعمل في هذا الكمبيوتر. يستخدم الرفاق {voice} بدلا منه.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "يحتاج OmniVoice إلى بطاقة رسوميات NVIDIA، ولا توجد بطاقة صالحة للعمل في هذا الكمبيوتر. تظهر الردود نصا. اختر Pocket في الإعدادات لتسمع الأصوات.",
    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "يحتاج OmniVoice إلى ذاكرة رسوميات حرة أكثر مما هو متاح إلى جانب اللعبة. يستخدم Pocket.",
    ["OmniVoice on AMD: set up first"] = "OmniVoice على AMD: يجب إعداده أولا",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "بعدها لن يعمل OmniVoice على هذه البطاقة حتى يعاد إعداده.",
    ["OmniVoice voice is ready."] = "صوت OmniVoice جاهز.",
    ["OmniVoice · Balanced"] = "OmniVoice · متوازن",
    ["OmniVoice · High Quality"] = "OmniVoice · جودة عالية",
    ["OmniVoice · Quality"] = "OmniVoice · جودة",
    ["OmniVoice · Ultra Quality"] = "OmniVoice · جودة فائقة",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · يحتاج حزمة Omni",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · يحتاج صوت Omni",
    ["OmniVoice’s code could not load in it"] = "تعذر تحميل كود OmniVoice داخله",
    ["On"] = "تشغيل",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "تشغيل، لكن تم اختيار صوت سحابي ضمن أصوات الرفاق، لذا لا يستخدم الخادم.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "تشغيل، لكن لا يوجد عنوان خادم محفوظ. لا يستطيع OmniVoice النطق بعد.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "تشغيل، لكن لا يوجد عنوان خادم محفوظ. يستخدم Pocket حتى تضيف عنوانا.",
    ["On, but no server address is saved. The server is not used yet."] = "تشغيل، لكن لا يوجد عنوان خادم محفوظ. لا يستخدم الخادم بعد.",
    ["On. Waiting for the conversation service."] = "تشغيل. في انتظار خدمة المحادثة.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "تشغيل: يتولى MIOpen الخاص ب AMD عمليات الالتفاف، مع MIOPEN_FIND_MODE=2 و MIOPEN_FIND_ENFORCE=1. إيقاف: عمليات الالتفاف الخاصة ب PyTorch. أيهما أسرع يعتمد على بطاقتك وتعريفها: إذا كانت الأصوات بطيئة أو تتوقف في منتصفها، جرب الخيار الآخر. لبطاقات AMD فقط. يعاد تشغيل OmniVoice بالاختيار الجديد عندما يكون خاملا.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "تشغيل: الشخصيات التي تخبرها بأنها تستطيع البقاء في مكانك تنتقل إلى شققك وتعيش فيها، ويمكنك اصطحابهم معك.\n\nإيقاف: لا يعمل أي شيء من هذا. عند الإيقاف تغادر شققك، لكن المود يتذكر من عاش هناك، لذا يعيدهم التشغيل.",
    ["One download of about {size} GB."] = "تنزيل واحد بحجم نحو {size} GB.",
    ["One download."] = "تنزيل واحد.",
    ["One file with versions, settings and the latest log lines. It never contains your API key, tokens, voice recordings or conversation text."] = "ملف واحد يضم الإصدارات والإعدادات وأحدث أسطر السجل. لا يحتوي أبدا على مفتاح API أو الرموز أو التسجيلات الصوتية أو نص المحادثات.",
    ["Only Mature models found. Turn on Mature content to use them."] = "لا توجد إلا نماذج للبالغين. فعل محتوى البالغين لاستخدامها.",
    ["Only https:// works outside this computer and your home network."] = "لا يعمل إلا https:// خارج هذا الكمبيوتر وشبكتك المنزلية.",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "تظهر هنا أول {count} مفضلة فقط. البقية موجودة في القائمة أدناه.",
    ["Open"] = "فتح",
    ["Open AI Companions in the Mods list."] = "افتح AI Companions في قائمة المودات.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "افتح r6/logs/redscript_rCURRENT.log. المود المذكور فيه هو سبب عدم تحميل النصوص البرمجية.",
    ["Open r6/logs/redscript_rCURRENT.log. Scripts did not compile. Match Scripts and game."] = "افتح r6/logs/redscript_rCURRENT.log. لم يتم تجميع النصوص البرمجية. طابق Scripts مع اللعبة.",
    ["Opened in your browser."] = "تم الفتح في متصفحك.",
    ["Opening Convai’s sign-in page in your browser…"] = "جاري فتح صفحة تسجيل الدخول إلى Convai في متصفحك…",
    ["Opening chat. Waiting for the conversation service."] = "جاري فتح الدردشة. في انتظار خدمة المحادثة.",
    ["Opening line"] = "سطر الافتتاح",
    ["Opening line for a named character"] = "سطر الافتتاح لشخصية لها اسم",
    ["Opening line for an ordinary person"] = "سطر الافتتاح لشخص عادي",
    ["Opening microphone…"] = "جاري فتح الميكروفون…",
    ["Opening the editor in your browser. Switch to your browser if it does not come to the front."] = "جاري فتح المحرر في متصفحك. انتقل إلى المتصفح إذا لم يظهر في المقدمة.",
    ["Opening the page in your browser…"] = "جاري فتح الصفحة في متصفحك…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "يفتح صفحة الدفع الخاصة ب Convai (Stripe) في متصفحك. تدفع ل Convai مباشرة، ولا يرى المود بطاقتك أبدا. يصبح اشتراكك فعالا بعد نحو 15 ثانية من الدفع، وعندها تستخدم المحادثات مفتاح Convai API الخاص بك.",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "يفتح صفحة تسجيل الدخول إلى Convai في متصفحك.\n\nسجل الدخول أو أنشئ حسابا مجانيا، وسيحفظ مفتاح Convai API على هذا الكمبيوتر، كما يحدث عند اللصق. لديك خمس دقائق.",
    ["Opens a text box over the game. Type part of a name and press Enter: the list shows every match on every page and letter. Esc leaves the list as it is, and Enter on an empty box shows the whole list again. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "يفتح مربع نص فوق اللعبة. اكتب جزءا من الاسم واضغط Enter: تعرض القائمة كل تطابق في كل الصفحات والحروف. يترك Esc القائمة كما هي، ويعرض Enter في المربع الفارغ القائمة كاملة من جديد. لا يهم حجم الأحرف ولا علامات النطق، ويجب أن تطابق كل كلمة تكتبها بداية كلمة في الاسم.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "يفتح convai.com في متصفحك. سجل الدخول أو أنشئ حسابا مجانيا، وانسخ مفتاح API، ثم عد واختر لصق بالأسفل.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "يفتح صفحة الفوترة الخاصة بك في Convai في متصفحك. سجل الدخول بحساب Convai نفسه لتغيير اشتراكك أو إلغائه.",
    ["Optional packs"] = "حزم اختيارية",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "اختياري. يستنسخ Pocket و OmniVoice وصوت Voxtral السحابي المقطع الذي تضيفه. بدونه تتحدث الشخصية بصوت عام يناسب جنسها.",
    ["Ordinary"] = "عادي",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "يهرب الأشخاص العاديون الذين تهددهم أو ينكمشون أو يقاومون، كما يفعل أمثالهم: يستخدم أفراد العصابات والحراس قبضاتهم عند الإهانة، وأسلحتهم عند التهديد بالقتل.\n\nقد يفعلون أيضا ما تطلبه منهم، إن كانوا سيفعلونه: أن ينبطحوا، أو يتوقفوا، أو يترجلوا من المركبة.\n\nالأشخاص العاديون فقط، وليس الشخصيات المسماة أو شخصيات القصة أبدا، ولا أثناء المشاهد أو المهام أو المعارك أبدا.",
