    ["Pocket could not load. See Help in Settings."] = "تعذر تحميل Pocket. راجع المساعدة في الإعدادات.",
    ["Pocket voice"] = "صوت Pocket",
    ["Pocket voice is ready."] = "صوت Pocket جاهز.",
    ["Pocket · On your PC"] = "Pocket · على جهازك",
    ["Pocket · Performance"] = "Pocket · الأداء",
    ["Pocket: the lightest, on your CPU, about 0.2 s to the first word.\n\nOmniVoice: richer, needs a capable GPU and its pack, 1 to 2.5 s.\n\nVoxtral: cloud voices with your Mistral key. The companions’ voice loads no local model; V’s typed lines follow V’s own voice setting.\n\nConvai: its own cloud voice. A voice that cannot run shows replies as text."] = "Pocket: الأخف، ويعمل على المعالج، ويصل إلى الكلمة الأولى خلال نحو 0.2 ثانية.\n\nOmniVoice: أغنى صوتا، ويحتاج إلى بطاقة رسوميات قوية وحزمته، ويستغرق من 1 إلى 2.5 ثانية.\n\nVoxtral: أصوات سحابية بمفتاح Mistral الخاص بك. صوت الرفاق لا يحمل أي نموذج محلي، والأسطر المكتوبة ل V تتبع إعداد صوت V نفسه.\n\nConvai: صوته السحابي الخاص. الصوت الذي لا يستطيع العمل يعرض الردود نصا.",
    ["PocketTTS model ({code})"] = "نموذج PocketTTS ({code})",
    ["Polish"] = "البولندية",
    ["Portuguese"] = "البرتغالية",
    ["Preparing connection to {name}…"] = "جاري تحضير الاتصال ب {name}…",
    ["Preparing to drive"] = "جاري التحضير للقيادة",
    ["Preparing {count} more companions…"] = "جاري تحضير {count} رفاق آخرين…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "جاري تحضير {name}: في انتظار فتح اتصال المحادثة…",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "جاري تحضير {name}: في انتظار اتصال خدمة المحادثة…",
    ["Preparing {name}: waiting for the game to place the character…"] = "جاري تحضير {name}: في انتظار أن تضع اللعبة الشخصية في مكانها…",
    ["Preparing {name}: waiting for the memory service…"] = "جاري تحضير {name}: في انتظار خدمة الذاكرة…",
    ["Preparing {name}: waiting for the voice model to load…"] = "جاري تحضير {name}: في انتظار تحميل نموذج الصوت…",
    ["Presence penalty"] = "عقوبة الحضور",
    ["Press Confirm to put every setting on this page back to its default."] = "اضغط تأكيد لإعادة كل إعداد في هذه الصفحة إلى افتراضيه.",
    ["Press Delete again to delete {name}."] = "اضغط حذف مرة أخرى لحذف {name}.",
    ["Press Enter to write  /  Esc to close"] = "اضغط Enter للكتابة  /  Esc للإغلاق",
    ["Press again"] = "اضغط مرة أخرى",
    ["Press again to delete this saved party. Anything else cancels."] = "اضغط مرة أخرى لحذف هذه المجموعة المحفوظة. أي شيء آخر يلغي الأمر.",
    ["Press it to open the Companion Manager while you play."] = "اضغطه لفتح إدارة الرفاق أثناء اللعب.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "اضغط للكتابة إلى جوني، صوت رأسك، أينما تتجه. يتطلب تفعيل جوني في رأسك من الإعدادات.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "اضغط للكتابة إلى الشخصية التي تواجهها. إن لم تكن تواجه أحدا، تكتب إلى أول عضو في مجموعتك.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "اضغط للكتابة إلى الشخصيات المحيطة بك دفعة واحدة. إن لم تكن تواجه أحدا، تكتب إلى أول عضو في مجموعتك واثنين آخرين منها.",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "اضغط عليه، ثم اضغط المفتاح أو زر وحدة التحكم الذي تريده. يلغي Esc أو B الأمر. يعمل فورا.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "اضغط المفتاح أو زر وحدة التحكم ل {action}. يلغي Esc أو B الأمر.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "اضغط للانتقال إلى الصفحة {page} من {pages}: {kind} من {first} إلى {last}.",
    ["Press {key} to open them."] = "اضغط {key} لفتحها.",
    ["Preview"] = "معاينة",
    ["Previous page"] = "الصفحة السابقة",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "الأسعار بالدولار الأمريكي. يمكنك الإلغاء في أي وقت من صفحة الفوترة في Convai.",
    ["Print screen"] = "Print screen",
    ["Privacy and help"] = "الخصوصية والمساعدة",
    ["Problem"] = "مشكلة",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "تم العثور على {count} مشكلة. اختر سطرا عليه علامة مشكلة لقراءة ما يجب فعله.",
    ["Profile only"] = "الملف الشخصي فقط",
    ["Prompting"] = "التوجيه",
    ["Puts every setting on this page back to its default. Other pages are not changed. Press the button twice to confirm."] = "يعيد كل إعداد في هذه الصفحة إلى الافتراضي. الصفحات الأخرى لا تتغير. اضغط الزر مرتين للتأكيد.",
    ["PyTorch is not installed in it"] = "PyTorch غير مثبت فيه",
    ["Pyjamas"] = "بيجاما",
    ["Quest and journal"] = "المهام واليوميات",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "لم يتم تحميل RED4ext. ثبته من Nexus Mods ثم أعد تشغيل اللعبة. وهو يشغل أيضا خدمة المحادثة.",
    ["RED4ext logs"] = "سجلات RED4ext",
