    ["Renamed to {name}."] = "تمت إعادة تسميته إلى {name}.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "توليد أصوات Pocket وOmniVoice على كمبيوتر آخر أو بطاقة رسومات أخرى: مفتاح التشغيل والإيقاف، وعنوان الخادم، واختبار الاتصال. يعمل ذلك أيا كان الصوت المختار أعلاه.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "توليد أصوات OmniVoice على كمبيوتر آخر أو بطاقة رسومات أخرى تشغل خادم OmniVoice.",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "توليد الأصوات على كمبيوتر آخر أو بطاقة رسومات أخرى تشغل خادم OmniVoice، حتى يحتفظ هذا الكمبيوتر بمعدل إطاراته.\n\nشغله، ثم اضغط تطبيق وأضف عنوان الخادم أدناه. سينطق الخادم بعدها كل اختيار من Pocket أو OmniVoice ضمن أصوات الرفاق، أما الصوت السحابي فيبقى كما اخترته. وإن تعذر الوصول إليه، تظهر الردود كنص، ويحاول المود مجددا كل بضع ثوان.",
    ["Reopen the manager; that action is no longer available."] = "أعد فتح الإدارة، فهذا الإجراء لم يعد متاحا.",
    ["Reopen this page after the memory service reconnects. A pending clear keeps waiting for its own result."] = "أعد فتح هذه الصفحة بعد إعادة اتصال خدمة الذاكرة. يبقى المسح المعلق بانتظار نتيجته الخاصة.",
    ["Repeat penalty"] = "عقوبة التكرار",
    ["Repeat the “where you are” sentence right before V’s words"] = "كرر جملة «أين أنت» مباشرة قبل كلام V",
    ["Replaces the characters of this saved party with the ones in your party now."] = "يستبدل شخصيات هذه المجموعة المحفوظة بالشخصيات الموجودة في مجموعتك الآن.",
    ["Replies in some languages show as text: this voice does not speak them. OmniVoice speaks them all, and Voxtral most of them."] = "تظهر الردود بلغات معينة كنص: هذا الصوت لا ينطقها. ينطق OmniVoice كلها، وVoxtral معظمها.",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "ردود تعرض على النموذج بعد القواعد. قد ينسخها نموذج صغير حرفيا، لذا لا تضف أي ردود، أو اجعلها قصيرة وبسيطة.",
    ["Reply length"] = "طول الرد",
    ["Reply length in words"] = "طول الرد بالكلمات",
    ["Report for the developer"] = "تقرير للمطور",
    ["Report path copied to the clipboard."] = "تم نسخ مسار التقرير إلى الحافظة.",
    ["Report saved: {path}"] = "تم حفظ التقرير: {path}",
    ["Request queued..."] = "الطلب في قائمة الانتظار...",
    ["Requires the Companion voices to be an OmniVoice choice"] = "يتطلب أن تكون أصوات الرفاق خيار OmniVoice",
    ["Requires the optional OmniVoice pack (GPU)"] = "يتطلب حزمة OmniVoice الاختيارية (GPU)",
    ["Reset everything"] = "إعادة ضبط كل شيء",
    ["Reset to default"] = "إعادة الضبط إلى الافتراضي",
    ["Restore defaults"] = "استعادة الافتراضي",
    ["Return to {page}."] = "العودة إلى {page}.",
    ["Revenge ambushes"] = "كمائن الانتقام",
    ["Revert changes"] = "التراجع عن التغييرات",
    ["Review the memory clear below, then choose Confirm or Cancel."] = "راجع مسح الذاكرة أدناه، ثم اختر تأكيد أو إلغاء.",
    ["Ride or die"] = "حتى النهاية",
    ["Right arrow"] = "Right arrow",
    ["Right now"] = "الآن",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "الآن: هي في طريقها بمجرد أن تكون مستعدة.\n\nبعد 2 أو 5 أو 10 دقائق: دقائق لعب حقيقية، فتصل في ذلك الوقت. ثم تنتظر بقدر هذا التأخير.",
    ["Right-now sentence"] = "جملة الآن",
    ["Romance"] = "الرومانسية",
    ["Romance animations"] = "الرسوم المتحركة الرومانسية",
    ["Romance line"] = "السطر الرومانسي",
    ["Romances"] = "قصص رومانسية",
    ["Romanian"] = "الرومانية",
    ["Romantic"] = "رومانسي",
    ["Rule {n}"] = "القاعدة {n}",
    ["Rule {n} is empty. Write the rule or delete it."] = "القاعدة {n} فارغة. اكتب القاعدة أو احذفها.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "القاعدة {n} طويلة جدا. اجعل كل قاعدة أقل من {max} حرفا.",
    ["Rule {n}, for Mature content"] = "القاعدة {n}، لمحتوى البالغين",
    ["Rule {n}, for a speaker with a reply length of its own"] = "القاعدة {n}، لمتحدث له طول رد خاص به",
    ["Rules for the whole world, used for every character in every talk: face to face, phone and group chats. Write facts and style, for example how people talk or what nobody knows. They never replace the mod’s own rules."] = "قواعد للعالم كله، تستخدم مع كل شخصية في كل حديث: وجها لوجه، وعبر الهاتف، وفي الدردشات الجماعية. اكتب الحقائق والأسلوب، مثل طريقة كلام الناس أو ما لا يعرفه أحد. لا تحل هذه القواعد محل قواعد المود أبدا.",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "شغل OmniVoice على بطاقة AMD Radeon باستخدام ROCm من AMD: تنزيل واحد، ويتم إعداده من هنا.",
    ["Running"] = "يعمل",
    ["Runtime files are old. Get the full install zip."] = "ملفات Runtime قديمة. احصل على ملف ZIP الكامل للتثبيت.",
    ["Runtime incomplete"] = "Runtime غير مكتمل",
    ["Runtime not loaded"] = "Runtime غير محمل",
    ["Russian"] = "الروسية",
    ["SELECTED"] = "مختار",
    ["SETTINGS"] = "الإعدادات",
    ["Same as speech"] = "مثل الكلام المنطوق",
    ["Sample character name"] = "اسم شخصية تجريبية",
    ["Sampling"] = "أخذ العينات",
    ["Save"] = "حفظ",
    ["Save clip"] = "حفظ المقطع",
    ["Save current party"] = "حفظ المجموعة الحالية",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "احفظ الشخصية أولا. بعدها يمكن أن يكون لها مقطع صوتي، وتبدأ في تذكر أحاديثك.",
    ["Saved Chat cleanup could not be verified. Please wait for the memory service."] = "تعذر التحقق من تنظيف الدردشات المحفوظة. انتظر خدمة الذاكرة.",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "تم الحفظ باسم {name}. اضغط «دعوة المجموعة» أسفله لدعوتهم مجددا.",
    ["Saved at {path}"] = "تم الحفظ في {path}",
    ["Saved clip: {seconds} seconds."] = "المقطع المحفوظ: {seconds} ثانية.",
    ["Saved on this computer only. Only the last four characters are ever shown."] = "محفوظ على هذا الكمبيوتر فقط. لا يظهر منه إلا آخر أربعة أحرف أبدا.",
    ["Saved party: {name}"] = "المجموعة المحفوظة: {name}",
    ["Saved reports"] = "التقارير المحفوظة",
    ["Saved."] = "تم الحفظ.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "تم الحفظ. المقطع طويل قليلا: أفضل نتائج تكون من 10 إلى 18 ثانية.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "تم الحفظ. المقطع قصير قليلا: أفضل نتائج تكون من 10 إلى 18 ثانية.",
    ["Saves a report file you can share on the mod’s Discord.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "يحفظ ملف تقرير يمكنك مشاركته على Discord الخاص بالمود.\n\nلا تدرج مفاتيح API والرموز والمعرفات وصوت الميكروفون ونص المحادثة. وبدون خدمة المحادثة يتم إنشاء تقرير أقصر من الملفات التي تستطيع اللعبة قراءتها.",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "يحفظ الشخصيات الموجودة في مجموعتك الآن، بما فيها النسخ وشخصياتك الخاصة، كمجموعة يمكنك دعوتها مجددا بضغطة واحدة. تسمى المجموعة 1 والمجموعة 2 وهكذا، وتظهر أدناه.\n\nيمكنك الاحتفاظ بما يصل إلى {count} من المجموعات المحفوظة.",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "قل خيار الحوار لاختياره: كلماته، أو جزءا منها، أو رقمه («اثنان»، «الأخير»). إن لم يتطابق شيء بوضوح فلن يتم اختيار شيء. لا تجيب أي شخصية.\n\nتضغط هذه الميزة مفاتيح الأسهم وEnter، لذا يجب أن تكون اللعبة في المقدمة. تحتاج إلى التعرف على الكلام على هذا الكمبيوتر، وتعمل سماعات الرأس بشكل أفضل.",
    ["Scenery or a vehicle is blocking the companion position."] = "عنصر من البيئة أو مركبة يعيق موقع الرفيق.",
    ["Scripts and Runtime"] = "Scripts وRuntime",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts مخصصة للعبة {scripts}، أما Runtime فمخصص ل {runtime}. يجب أن يتطابقا. انظر المساعدة في الإعدادات.",
    ["Scripts {scripts} and Runtime {runtime} do not match. If the Scripts are older, install the update zip from Nexus Mods. If the Runtime is older, install the full install zip (AI-Companions-LLM). Extract into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} وRuntime {runtime} غير متطابقين. إن كانت Scripts أقدم، فثبت ملف ZIP للتحديث من Nexus Mods. وإن كان Runtime أقدم، فثبت ملف ZIP الكامل للتثبيت (AI-Companions-LLM). فك الضغط في مجلد Cyberpunk 2077، ثم أعد تشغيل اللعبة.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} وRuntime {runtime} غير متطابقين: Runtime قديم. فك ضغط ملف ZIP الكامل للتثبيت (AI-Companions-LLM، على Nexus Mods) داخل مجلد Cyberpunk 2077، ثم أعد تشغيل اللعبة.",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} وRuntime {runtime}.",
    ["Scripts {scripts} on Runtime base {runtime}."] = "Scripts {scripts} على أساس Runtime {runtime}.",
    ["Scroll lock"] = "Scroll lock",
    ["Search"] = "بحث",
    ["Search by name"] = "البحث بالاسم",
    ["Search characters"] = "البحث عن الشخصيات",
    ["Search models"] = "البحث عن النماذج",
    ["Search names, models or settings..."] = "ابحث عن الأسماء أو النماذج أو الإعدادات...",
    ["Section headings"] = "عناوين الأقسام",
    ["See the characters you have talked to and how close each one is to you: the bond level, what raised or hurt it, their quests and the stories they are in."] = "اطلع على الشخصيات التي تحدثت إليها ومدى قربها منك: مستوى العلاقة، وما رفعها أو أضر بها، ومهامها، والقصص التي تشارك فيها.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "اطلع على ما تتذكره كل شخصية، واجعل واحدة منها أو جميعها تنسى.\n\nتبقى الذكريات محفوظة عبر عمليات الحفظ.",
    ["Select a destination on the map first."] = "اختر وجهة على الخريطة أولا.",
    ["Select {name} for memory controls. This does not invite them or change their conversation settings."] = "اختر {name} لعناصر تحكم الذاكرة. لا يدعو ذلك الشخصية، ولا يغير إعدادات محادثتها.",
    ["Selected"] = "مختار",
    ["Selected character"] = "الشخصية المختارة",
    ["Send error reports automatically"] = "إرسال تقارير الأخطاء تلقائيا",
    ["Send the generated report rather than raw log files. Open these locations only if the developer asks for a specific file."] = "أرسل التقرير المنشأ بدلا من ملفات السجل الخام. افتح هذه المواقع فقط إذا طلب المطور ملفا محددا.",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "يرسل رسالة صغيرة واحدة إلى نقطة النهاية الخاصة بك باستخدام معرف النموذج والمفتاح المحفوظين، ويعرض الرد. يكاد لا يستهلك من رصيدك شيئا.",
    ["Serbian"] = "الصربية",
    ["Server address"] = "عنوان الخادم",
    ["Service not running"] = "الخدمة لا تعمل",
    ["Service not running ({reason})"] = "الخدمة لا تعمل ({reason})",
    ["Service starting"] = "جار بدء الخدمة",
    ["Set from the start: F7 talk by voice, F6 talk by text, F10 group voice chat, F8 group text chat and F4 the Companion Manager. Clear one and it stays clear. Restore defaults brings them back."] = "معينة من البداية: F7 للتحدث بالصوت، وF6 للتحدث بالنص، وF10 للدردشة الصوتية الجماعية، وF8 للدردشة النصية الجماعية، وF4 لإدارة الرفاق. امسح أحدها فيبقى فارغا. استعادة الافتراضي يعيدها.",
    ["Set up OmniVoice for AMD"] = "إعداد OmniVoice ل AMD",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "أعد OmniVoice على بطاقة AMD Radeon بتنزيل واحد، واختر طريقة تشغيله.",
    ["Settings"] = "الإعدادات",
    ["Settings are active, but could not be saved for next time."] = "الإعدادات مفعلة، لكن تعذر حفظها للمرة القادمة.",
    ["Settings saved."] = "تم حفظ الإعدادات.",
    ["Setup check"] = "فحص الإعداد",
    ["Shared across your saves"] = "مشتركة بين عمليات الحفظ",
    ["She texts you"] = "ترسل لك رسالة نصية",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "ترسل لك رسالة نصية عند وصولها، وعند إلغائك، وعندما تستسلم. إيقاف: لا رسائل (لكنها تتذكر أنك لم تحضر الموعد).",
    ["Shift"] = "Shift",
    ["Shipped: off"] = "الأصلي: متوقف",
    ["Shipped: the mod’s own limit"] = "الأصلي: حد المود نفسه",
    ["Shipped: {value}"] = "الأصلي: {value}",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "حقائق قصيرة تكتبها بنفسك، مثل اسم أو وعد. تعرفها الشخصية في كل حديث.",
    ["Short report saved because the conversation service could not build the full report: {path}"] = "تم حفظ تقرير مختصر لأن خدمة المحادثة تعذر عليها إنشاء التقرير الكامل: {path}",
    ["Short report saved because the conversation service did not answer: {path}"] = "تم حفظ تقرير مختصر لأن خدمة المحادثة لم تستجب: {path}",
    ["Short report saved because the conversation service is not running: {path}"] = "تم حفظ تقرير مختصر لأن خدمة المحادثة لا تعمل: {path}",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "قواعد قصيرة تلتزم بها هذه الشخصية دائما عند الكلام، مثلا: لا تشتم أبدا. أجب في جملة واحدة.",
    ["Short summary of earlier talks"] = "ملخص قصير للأحاديث السابقة",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "اختصر ما يقرؤه النموذج، لتصبح الردود أسرع. تبقى حدود المود نفسها سارية، لذلك لا تستطيع هذه الإعدادات إلا جعل الأمور أقصر.",
    ["Shorter: up to about {words} words"] = "أقصر: حتى نحو {words} كلمة",
    ["Show companion reply subtitles during conversations."] = "عرض ترجمة ردود الرفاق النصية أثناء المحادثات.",
    ["Show only the models whose name starts with this letter."] = "اعرض النماذج التي يبدأ اسمها بهذا الحرف فقط.",
    ["Side character"] = "شخصية جانبية",
    ["Side characters"] = "الشخصيات الجانبية",
    ["Side characters to invite"] = "الشخصيات الجانبية للدعوة",
    ["Sign in"] = "تسجيل الدخول",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "سجل الدخول في صفحة Convai من متصفحك. يحفظ مفتاحك هنا عند الانتهاء.",
    ["Sign in with Convai"] = "تسجيل الدخول عبر Convai",
    ["Signed in. Your Convai API key is saved."] = "تم تسجيل الدخول. تم حفظ مفتاح Convai API الخاص بك.",
    ["Sit down and take a place"] = "اجلس واختر مقعدا",
    ["Slovak"] = "السلوفاكية",
    ["Slovenian"] = "السلوفينية",
    ["Solo look"] = "المظهر المنفرد",
    ["Some Runtime files are from a newer update than this Runtime says. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder again. Then restart the game."] = "بعض ملفات Runtime أحدث من الإصدار المسجل فيه. فك ضغط ملف ZIP الكامل للتثبيت (AI-Companions-LLM، على Nexus Mods) في مجلد Cyberpunk 2077 مجددا. ثم أعد تشغيل اللعبة.",
    ["Some game models have special rigs or roles and may not behave as ordinary companions."] = "بعض نماذج اللعبة لها هياكل أو أدوار خاصة، وقد لا تتصرف كرفاق عاديين.",
    ["Some mod files are missing. Extract the update zip again. See Help in Settings."] = "بعض ملفات المود مفقودة. فك ضغط ملف ZIP للتحديث مجددا. انظر المساعدة في الإعدادات.",
    ["Some model records could not be read."] = "تعذرت قراءة بعض سجلات النماذج.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "تعذر نقل بعض ملفات الحزمة إلى أماكنها لأن ملفات مختلفة موجودة فيها بالفعل. فك ضغط الحزمة في مجلد Cyberpunk 2077 مجددا، ودع الملفات تحل محلها.",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "استجاب شيء ما، لكنه ليس خادم OmniVoice. تحقق من المنفذ.",
    ["Something came up and I can't make it. Sorry."] = "حدث أمر طارئ ولن أستطيع الحضور. آسف.",
    ["Something on this PC (a firewall or security software) is blocking the connection to the model server you added."] = "شيء ما على هذا الكمبيوتر (جدار ناري أو برنامج أمان) يحجب الاتصال بخادم النموذج الذي أضفته.",
    ["Space"] = "Space",
    ["Spanish"] = "الإسبانية",
    ["Spawn"] = "دعوة",
    ["Spawn party"] = "دعوة المجموعة",
    ["Speak dialogue choices"] = "نطق خيارات الحوار",
    ["Speak now"] = "تحدث الآن",
    ["Speaking a choice needs speech recognition on this PC."] = "لنطق خيار يلزم التعرف على الكلام على هذا الكمبيوتر.",
    ["Speaking rules"] = "قواعد الكلام",
    ["Speaking style"] = "أسلوب الكلام",
    ["Speaks up normally"] = "يتحدث بشكل عادي",
    ["Speaks up often"] = "يتحدث كثيرا",
    ["Speaks up rarely"] = "يتحدث نادرا",
    ["Speech line"] = "سطر الكلام",
    ["Speech: {list}"] = "الكلام: {list}",
    ["Stand near one of your owned cars, or summon one."] = "قف بالقرب من إحدى سياراتك، أو استدع واحدة.",
    ["Stand near your owned car."] = "قف بالقرب من سيارتك.",
    ["Stand up to open the Companion Manager"] = "انهض لفتح إدارة الرفاق",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "شغل خادم OmniVoice على الكمبيوتر الآخر. تظهر نافذته العنوان الذي يجب استخدامه، مثلا 192.168.1.20:8765. انسخه، ثم اختر لصق العنوان. يتم قراءته من الحافظة مرة واحدة ويتم حفظه على هذا الكمبيوتر.\n\nعلى الكمبيوتر نفسه استخدم 127.0.0.1:8765. يمكنك أيضا كتابة address=192.168.1.20:8765 في الملف player-remote-omnivoice.txt داخل مجلد خدمة المحادثة.\n\nلا يتم إرسال شيء إليه إلا بعد تفعيل OmniVoice عن بعد واختيار OmniVoice، أو بعد الضغط على اختبار الاتصال.",
    ["Starting"] = "جار البدء",
    ["Starting the AMD setup…"] = "جار بدء إعداد AMD…",
    ["Starting trip"] = "جار بدء الرحلة",
    ["Starts with"] = "يبدأ ب",
    ["Starts with: {letter}"] = "يبدأ بالحرف: {letter}",
    ["State: {state}"] = "الحالة: {state}",
    ["Status"] = "الحالة",
    ["Step out and wait for the previous driver cleanup to finish."] = "انزل وانتظر حتى ينتهي تحرير السائق السابق.",
    ["Step out before starting a new companion trip."] = "انزل قبل بدء رحلة جديدة مع رفيق.",
    ["Step out of the driver seat before asking your companion to drive."] = "انزل من مقعد السائق قبل أن تطلب من رفيقك القيادة.",
    ["Step out of the driver seat so your companion can get in."] = "انزل من مقعد السائق ليتمكن رفيقك من الركوب.",
    ["Stop requested"] = "تم طلب الإيقاف",
    ["Stop text {n}"] = "نص الإيقاف {n}",
    ["Stop texts"] = "نصوص الإيقاف",
    ["Stop the trip after returning to gameplay. Wait for the car to stop, then step out before dismissing the driver."] = "أوقف الرحلة بعد العودة إلى اللعب. انتظر حتى تتوقف السيارة، ثم انزل قبل صرف السائق.",
    ["Stop the trip and step out before dismissing your driver."] = "أوقف الرحلة وانزل قبل صرف سائقك.",
    ["Stop trip"] = "إيقاف الرحلة",
    ["Stopping"] = "جار الإيقاف",
    ["Stopping the trip. Wait for the car to stop before stepping out."] = "جار إيقاف الرحلة. انتظر حتى تتوقف السيارة قبل النزول.",
    ["Story"] = "القصة",
    ["Story character"] = "شخصية القصة",
    ["Story packs"] = "حزم القصص",
