    ["Street clothes"] = "ملابس الشارع",
    ["Street reputation"] = "سمعة الشارع",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "لغة قوية، وعنف فاضح، ومخدرات، ومغازلة وجنس بين البالغين المتراضين. للبالغين فقط (18+). يحتاج إلى Local AI أو مخصص.",
    ["Subtitle language"] = "لغة الترجمة النصية",
    ["Subtitles"] = "الترجمة النصية",
    ["Subtitles in another language need Gemini, Mistral, Custom or Local AI. Convai cannot translate them."] = "تحتاج الترجمة النصية بلغة أخرى إلى Gemini أو Mistral أو مخصص أو Local AI. لا يستطيع Convai ترجمتها.",
    ["Suit"] = "بدلة",
    ["Support report saved: {path}"] = "تم حفظ تقرير الدعم: {path}",
    ["Swedish"] = "السويدية",
    ["Switch back on"] = "تشغيل مجددا",
    ["Switched back on."] = "تم التشغيل مجددا.",
    ["Switched off"] = "متوقف",
    ["Switched off, they say nothing about fights or about what you pick up."] = "عند الإيقاف لا يتحدثون عن القتال أو عما تلتقطه.",
    ["Switched off."] = "متوقف.",
    ["T-shirt"] = "تي شيرت",
    ["TALK TO {character}"] = "تحدث إلى {character}",
    ["TEXT  >"] = "النص  >",
    ["Tab"] = "Tab",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "يجلس بجانبك على مقعد حين تجلس، ويشغل مقعدا أو مكانا في شقتك. عند الإيقاف يبقون واقفين بجانبك.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "يزيل {name} من المفضلة. يبقى موضعه في القائمة أدناه.",
    ["Talk by text"] = "التحدث بالنص",
    ["Talk by voice"] = "التحدث بالصوت",
    ["Talk to Johnny by text"] = "تحدث إلى جوني بالنص",
    ["Talk to Johnny by voice"] = "تحدث إلى جوني بالصوت",
    ["Talk to a character and your bond with them shows here."] = "تحدث إلى شخصية وستظهر علاقتك بها هنا.",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "التحدث إلى الشخصيات غير الرئيسية متوقف. فعله من Esc > Mods.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "تحدث بدون مفتاح. عندما تواجه شخصية أو يكون رفيق قريبا، يستمع التعديل ويرد عندما تتوقف لثانية تقريبا.\n\nلا يعمل أبدا أثناء المشاهد الخاصة باللعبة أو خياراتها، ولا عندما تتكلم شخصية. لا يغادر أي شيء جهازك إلا عند سماع كلام. سماعات الرأس هي الأفضل، لكن ميكروفون سماعة البلوتوث ينزل بالجودة إلى مستوى المكالمات أثناء الاستماع.",
    ["Talking gestures"] = "إيماءات الكلام",
    ["Tank top"] = "فانيلة",
    ["Temperature"] = "درجة الحرارة",
    ["Test"] = "اختبار",
    ["Test connection"] = "اختبار الاتصال",
    ["Testing it on your card…"] = "يجري الاختبار على بطاقتك…",
    ["Testing the connection…"] = "جار اختبار الاتصال…",
    ["Testing…"] = "جار الاختبار…",
    ["Text only (no voice)"] = "نص فقط (بدون صوت)",
    ["That action is not available."] = "هذا الإجراء غير متاح.",
    ["That address is a web page, not the API. For OpenRouter use https://openrouter.ai/api/v1."] = "هذا العنوان صفحة ويب وليس API. ل OpenRouter استخدم https://openrouter.ai/api/v1.",
    ["That address is a web page, not the API. Use the API address from your provider."] = "هذا العنوان صفحة ويب وليس API. استخدم عنوان API من مزودك.",
    ["That character model is unavailable."] = "نموذج هذه الشخصية غير متاح.",
    ["That character was not found."] = "لم يعثر على هذه الشخصية.",
    ["That choice is not available."] = "هذا الخيار غير متاح.",
    ["That companion is no longer in your party."] = "هذا الرفيق لم يعد في مجموعتك.",
    ["That companion is no longer ready to drive."] = "هذا الرفيق لم يعد جاهزا للقيادة.",
    ["That companion is not available."] = "هذا الرفيق غير متاح.",
    ["That confirmation is no longer active."] = "هذا التأكيد لم يعد نشطا.",
    ["That conversation profile is unavailable."] = "ملف تعريف المحادثة هذا غير متاح.",
    ["That copy is no longer in your party."] = "هذه النسخة لم تعد في مجموعتك.",
    ["That dismissal is no longer pending."] = "هذا الإعفاء لم يعد معلقا.",
    ["That entry cannot be a favorite."] = "لا يمكن أن يكون هذا العنصر من المفضلة.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "هذا الملف ليس تسجيلا يمكن للأصوات قراءته. استخدم ملف WAV أو MP3 أو OGG أو FLAC.",
    ["That file is too big for a voice clip."] = "هذا الملف كبير جدا لمقطع صوتي.",
    ["That is not valid JSON."] = "هذا ليس JSON صالحا.",
    ["That is too long."] = "هذا طويل جدا.",
    ["That key is already used for another action."] = "هذا المفتاح مستخدم بالفعل لإجراء آخر.",
    ["That look is not one of this character’s."] = "هذا المظهر ليس من مظاهر هذه الشخصية.",
    ["That model is no longer available."] = "لم يعد هذا النموذج متاحا.",
    ["That party no longer exists."] = "هذه المجموعة لم تعد موجودة.",
    ["That person cannot be switched off."] = "لا يمكن إيقاف هذا الشخص.",
    ["That prompting option was not found."] = "لم يعثر على خيار الموجه هذا.",
    ["That setting is read-only."] = "هذا الإعداد للقراءة فقط.",
    ["That was not accepted."] = "لم يتم قبول ذلك.",
    ["The AMD setup was removed."] = "تمت إزالة إعداد AMD.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "تحتاج إدارة الرفاق إلى Mod Configuration Menu 0.10.5 أو أحدث، أو Native Settings UI",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI {nsui} or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "تحتاج إدارة الرفاق إلى Mod Configuration Menu 0.10.5 أو أحدث، أو Native Settings UI {nsui} أو أحدث. يكفي أي منهما. ثبت أحدهما من Nexus Mods، ثم أعد تشغيل اللعبة.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "لا يستطيع صوت Convai السحابي استخدام الكلام الطبيعي، لذلك تم إيقافه.",
    ["The Convai daily limit is used up. It resets at {time}. Choose another provider in Settings, or invite again then."] = "انتهى الحد اليومي ل Convai. يعاد ضبطه عند {time}. اختر مزودا آخر في الإعدادات، أو ادع مجددا عندها.",
    ["The Gemini model is not available right now. Try again later or use Local AI."] = "نموذج Gemini غير متاح الآن. حاول لاحقا أو استخدم Local AI.",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "نموذج Local AI الذي اخترته مفقود، أو لا يتسع في ذاكرة الرسوميات الحرة، أو لم يبدأ، لذلك استخدم {model} بدلا منه.",
    ["The Local AI model you chose needs about {need} MB of graphics memory, but only {available} MB are available for it beside the game, so {model} was used instead."] = "يحتاج نموذج Local AI الذي اخترته إلى نحو {need} MB من ذاكرة الرسوميات، لكن لا يتوفر له بجانب اللعبة سوى {available} MB، لذلك استخدم {model} بدلا منه.",
    ["The Local AI pack finds these. It is not installed or not ready, so none are collected now."] = "تجد حزمة Local AI هذه. إنها غير مثبتة أو غير جاهزة، لذلك لا يتم جمع أي منها الآن.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "تمنح نماذج حزمة Mature غير المقيدة (ل Local AI) التأثير الكامل، أما النماذج العادية فترفض الجنس في الغالب. الحزمة: مثبتة.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "تمنح نماذج حزمة Mature غير المقيدة (ل Local AI) التأثير الكامل، أما النماذج العادية فترفض الجنس في الغالب. الحزمة: غير مثبتة (اختيارية، في صفحة هذا التعديل على Hugging Face).",
    ["The Mistral model is unavailable right now. Try again in a minute."] = "نموذج Mistral غير متاح الآن. حاول مجددا بعد دقيقة.",
    ["The OmniVoice pack is not installed. Install it first."] = "حزمة OmniVoice غير مثبتة. ثبتها أولا.",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "لا يمكن الوصول إلى خادم OmniVoice. تظهر الردود كنص حتى يجيب. يسأله التعديل مجددا كل بضع ثوان.",
    ["The Pocket voice (V’s voice, and a companion’s when you chose Pocket) could not start, so it stays silent. Pocket is part of the Runtime: nothing else needs installing. Restart the game. If it happens again, save a report below and share it on the mod’s Discord."] = "تعذر تشغيل صوت Pocket (صوت V، وصوت الرفيق عندما تختار Pocket)، لذلك يبقى صامتا. Pocket جزء من Runtime، ولا يحتاج شيئا آخر للتثبيت. أعد تشغيل اللعبة. إن تكرر الأمر، احفظ تقريرا من الأسفل وشاركه على Discord الخاص بالمود.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "ملف Runtime مخصص للعبة {other}، ونسختك للعبة {game}. احصل على ملف ZIP الكامل للتثبيت ل {game}.",
    ["The Runtime is incomplete ({code}). Extract the full install zip (AI-Companions-LLM) into the Cyberpunk 2077 folder again and let it replace the files, then restart the game."] = "Runtime غير مكتمل ({code}). استخرج ملف ZIP الكامل للتثبيت (AI-Companions-LLM) داخل مجلد Cyberpunk 2077 مجددا واسمح له باستبدال الملفات، ثم أعد تشغيل اللعبة.",
    ["The Runtime is older than {required}. Get the full install zip."] = "Runtime أقدم من {required}. احصل على ملف ZIP الكامل للتثبيت.",
    ["The Runtime is out of date. Get the full install zip."] = "Runtime غير محدث. احصل على ملف ZIP الكامل للتثبيت.",
    ["The Runtime is too old for voices. Install the Full file from Nexus Mods."] = "Runtime قديم جدا للأصوات. ثبت ملف Full من Nexus Mods.",
    ["The Runtime update from {from} to {to} was never applied, so some Runtime files are old. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "لم يطبق تحديث Runtime من {from} إلى {to} أبدا، لذلك بعض ملفات Runtime قديمة. استخرج ملف ZIP الكامل للتثبيت (AI-Companions-LLM، على Nexus Mods) داخل مجلد Cyberpunk 2077، ثم أعد تشغيل اللعبة.",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "تم تحميل إضافة Runtime، لكن خدمة المحادثة لم تترك أي أثر في هذه الجلسة. يوضح launcher.log في red4ext/plugins/AiNpcCyberpunkCode السبب: launcher.ini متوقف، أو Node غير موجود، أو برنامج أمان يمنع Node. أصلح ذلك، ثم أعد تشغيل اللعبة.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "ملفات Scripts و Runtime غير متطابقة. حدث الأقدم منهما. راجع المساعدة في الإعدادات.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "ملفات Scripts مخصصة للعبة {other}، ونسختك للعبة {game}. احصل على ملف ZIP للتحديث ل {game}.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts من إصدار اللعبة {scripts}، و Runtime من إصدار اللعبة {runtime}، وإصدار لعبتك لا يطابق أيا منهما. استخرج ملف ZIP الكامل للتثبيت المعد للعبة نفسها التي تملكها (من Nexus Mods) داخل مجلد Cyberpunk 2077، ثم أعد تشغيل اللعبة.",
    ["The account is out of credits. Add credits with your provider."] = "رصيد الحساب نفد. أضف رصيدا عبر مزودك.",
    ["The action could not finish: {reason}"] = "تعذر إكمال الإجراء: {reason}",
    ["The address must start with https:// or http://."] = "يجب أن يبدأ العنوان ب https:// أو http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "العنوان يحولك إلى مكان آخر. استخدم العنوان النهائي من مزودك.",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "عنوان مزودك المتوافق مع OpenAI ومفتاح API ومعرف النموذج، واختبار الاتصال. يستخدم عندما يكون مخصص هو مزود المحادثة.",
    ["The bio is too long. Keep it under {max} characters."] = "النبذة طويلة جدا. اجعلها أقل من {max} حرفا.",
    ["The bio is too short. Use at least {max} characters."] = "النبذة قصيرة جدا. استخدم {max} حرفا على الأقل.",
    ["The borrowed car is in use."] = "السيارة المستعارة قيد الاستخدام.",
    ["The borrowed car is unavailable."] = "السيارة المستعارة غير متاحة.",
    ["The browser for the conversation page would not start. Try again, or use another Chromium browser."] = "تعذر تشغيل المتصفح الخاص بصفحة المحادثة. حاول مجددا، أو استخدم متصفح Chromium آخر.",
    ["The browser in browser.txt did not work, so the automatic one is used."] = "لم يعمل المتصفح المحدد في browser.txt، لذلك يتم استخدام المتصفح التلقائي.",
    ["The car has stopped. Step out so your companion can leave the driver seat."] = "توقفت السيارة. انزل حتى يتمكن رفيقك من ترك مقعد السائق.",
    ["The car is now in use. The companion trip was cancelled."] = "السيارة قيد الاستخدام الآن. ألغيت رحلة الرفيق.",
    ["The character count changed. Review Forget all memories again."] = "تغير عدد الشخصيات. راجع «نسيان كل الذكريات» مجددا.",
    ["The character died before joining."] = "توفيت الشخصية قبل الانضمام.",
    ["The character was removed before joining."] = "أزيلت الشخصية قبل الانضمام.",
    ["The characters of this party: {names}."] = "شخصيات هذه المجموعة: {names}.",
    ["The characters you have talked to and how close each one is to you. The most recent come first."] = "الشخصيات التي تحدثت إليها ومدى قربك من كل منها. الأحدث يظهر أولا.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "المقطع صامت في معظمه. استخدم مقطعا يتحدث فيه أحدهم معظم الوقت.",
    ["The clip is too long. Use at most {max} seconds."] = "المقطع طويل جدا. استخدم {max} ثانية كحد أقصى.",
    ["The clip is too short. Use at least {min} seconds."] = "المقطع قصير جدا. استخدم {min} ثانية على الأقل.",
    ["The clipboard could not be read."] = "تعذر قراءة الحافظة.",
    ["The clipboard does not hold a Convai API key."] = "الحافظة لا تحتوي على مفتاح API ل Convai.",
    ["The clipboard does not hold a model ID."] = "الحافظة لا تحتوي على معرف نموذج.",
    ["The clipboard does not hold a server address."] = "الحافظة لا تحتوي على عنوان خادم.",
    ["The clipboard does not hold a web address."] = "الحافظة لا تحتوي على عنوان ويب.",
    ["The clipboard does not hold an API key."] = "الحافظة لا تحتوي على مفتاح API.",
    ["The clipboard is empty. Copy it first."] = "الحافظة فارغة. انسخ شيئا أولا.",
    ["The clipboard is empty. Copy the address first."] = "الحافظة فارغة. انسخ العنوان أولا.",
    ["The clipboard is empty. Copy your key first."] = "الحافظة فارغة. انسخ مفتاحك أولا.",
    ["The clipboard is not available here. Read the path from the Last report row."] = "الحافظة غير متاحة هنا. اقرأ المسار من صف «آخر تقرير».",
    ["The companion binding changed."] = "تغير ربط الرفيق.",
    ["The companion could not finish entering the driver seat."] = "تعذر على الرفيق إكمال الجلوس في مقعد السائق.",
    ["The companion left the driver seat."] = "غادر الرفيق مقعد السائق.",
    ["The companion, car, seat or selected destination changed. Ask again."] = "تغير الرفيق أو السيارة أو المقعد أو الوجهة المختارة. اطلب مجددا.",
    ["The connection test failed."] = "فشل اختبار الاتصال.",
    ["The connection works. The endpoint accepted your model and key."] = "الاتصال يعمل. قبلت نقطة النهاية النموذج والمفتاح.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "لم يفتح اتصال المحادثة. تحقق من اتصالك، ثم ادع مجددا.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "خدمة المحادثة لا تستطيع الوصول إلى الإنترنت. راجع المساعدة في الإعدادات.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "خدمة المحادثة لا تستطيع الوصول إلى {host}. اسمح ل Node.js عبر جدار الحماية أو برنامج الحماية (يسألك Windows مرة واحدة، فاختر السماح)، وتحقق من اتصالك بالإنترنت، ثم أعد تشغيل اللعبة.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "خدمة المحادثة لا ترى مجلد هذا التعديل داخل اللعبة: مجلدات افتراضية لمدير التعديلات، أو مجلد لا يسمح لها بقراءته. استخرج Runtime مباشرة داخل مجلد Cyberpunk 2077، أو شغل اللعبة من مدير التعديلات الذي يحتوي على Runtime.",
    ["The conversation service could not reply. Please try again."] = "تعذر على خدمة المحادثة الرد. حاول مجددا.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, save a report below and share it on the mod’s Discord."] = "تعذر تشغيل خدمة المحادثة ({code}). أعد تشغيل اللعبة. إن تكرر الأمر، احفظ تقريرا من الأسفل وشاركه على Discord الخاص بالمود.",
    ["The conversation service could not start. Restart the game, or see Help in Settings."] = "تعذر تشغيل خدمة المحادثة. أعد تشغيل اللعبة، أو راجع المساعدة في الإعدادات.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "لم ترد خدمة المحادثة على فحص الإعداد، لذلك يرجح أن Runtime الخاص بها أقدم من ملفات Scripts هذه. استخرج ملف ZIP الكامل للتثبيت (AI-Companions-LLM، على Nexus Mods) داخل مجلد Cyberpunk 2077، ثم أعد تشغيل اللعبة.",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "لم ترد خدمة المحادثة. انتظر لحظة، ثم ادع مجددا.",
    ["The conversation service did not get that message. Try again."] = "لم تستلم خدمة المحادثة تلك الرسالة. حاول مجددا.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "لم تبدأ خدمة المحادثة. هل Runtime مثبت؟ راجع المساعدة في الإعدادات.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "خدمة المحادثة لا تعمل، لذلك لا يمكن إجراء أي اختبار. أعد تشغيل اللعبة.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "خدمة المحادثة لا تعمل، لذلك لا يمكن عرض الخطط. أعد تشغيل اللعبة.",
    ["The conversation service is not running, so the editor cannot open. Restart the game."] = "خدمة المحادثة لا تعمل، لذلك لا يمكن فتح المحرر. أعد تشغيل اللعبة.",
    ["The conversation service is not running. Restart the game to start it again."] = "خدمة المحادثة لا تعمل. أعد تشغيل اللعبة لتشغيلها مجددا.",
    ["The conversation service is not running. Restart the game."] = "خدمة المحادثة لا تعمل. أعد تشغيل اللعبة.",
    ["The conversation service is starting. Try again in a few seconds."] = "خدمة المحادثة قيد التشغيل. حاول مجددا بعد ثوان قليلة.",
    ["The conversation service needs a Chromium browser such as Microsoft Edge, Google Chrome, Brave or Opera. Install one, or put the path of yours in a browser.txt file in the red4ext/plugins/AiNpcCyberpunkMod folder of the game (no launcher.ini is needed), then restart the game."] = "تحتاج خدمة المحادثة إلى متصفح Chromium، مثل Microsoft Edge أو Google Chrome أو Brave أو Opera. ثبت أحدها، أو ضع مساره في ملف browser.txt داخل مجلد red4ext/plugins/AiNpcCyberpunkMod في اللعبة (لا حاجة إلى launcher.ini)، ثم أعد تشغيل اللعبة.",
    ["The conversation service needs your Convai API key. Add it, then restart the game."] = "تحتاج خدمة المحادثة إلى مفتاح API الخاص بك ل Convai. أضفه، ثم أعد تشغيل اللعبة.",
    ["The conversation service restarted. Please try again."] = "أعيد تشغيل خدمة المحادثة. حاول مجددا.",
    ["The conversation service runs beside the game. If it is not running, restart the game. Its logs are listed below."] = "تعمل خدمة المحادثة بجانب اللعبة. إن لم تكن تعمل، أعد تشغيل اللعبة. سجلاتها مدرجة أدناه.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "بدئت خدمة المحادثة لكنها لم تبلغ عن نفسها أبدا. على الأرجح أوقفها برنامج أمان فورا، أو أن Node لا يعمل على هذا الجهاز. اسمح ب red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe في برنامج الأمان لديك، ثم أعد تشغيل اللعبة.",
    ["The conversation service writes bridge.stderr.log, bridge.stdout.log and bridge-service.log in {path}"] = "تكتب خدمة المحادثة الملفات bridge.stderr.log و bridge.stdout.log و bridge-service.log في {path}",
    ["The copy could not be dismissed."] = "تعذر إعفاء هذه النسخة.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "المزود المخصص يحد من طلباتك. حاول مجددا بعد لحظة.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "يفيد المزود المخصص بأن رصيد حسابك نفد. أضف رصيدا هناك، ثم حاول مجددا.",
    ["The download did not finish. Check your connection and try again."] = "لم يكتمل التنزيل. تحقق من اتصالك وحاول مجددا.",
    ["The download is not ready yet in this version of the mod."] = "التنزيل غير جاهز بعد في هذا الإصدار من التعديل.",
    ["The downloaded files did not check out. Try again."] = "الملفات المنزلة لم تجتز الفحص. حاول مجددا.",
    ["The driver seat is occupied or reserved."] = "مقعد السائق مشغول أو محجوز.",
    ["The driver seat was not released, so the trip was cancelled."] = "لم يفرج عن مقعد السائق، لذلك ألغيت الرحلة.",
    ["The driving request could not be cancelled."] = "تعذر إلغاء طلب القيادة.",
    ["The driving request could not be queued."] = "تعذر وضع طلب القيادة في قائمة الانتظار.",
    ["The eddies could not be moved."] = "تعذر نقل الإيدي.",
    ["The editor could not be opened. Try again."] = "تعذر فتح المحرر. حاول مجددا.",
    ["The editor is closed. You can close this tab."] = "المحرر مغلق. يمكنك إغلاق هذا التبويب.",
    ["The editor keeps choices for {max} characters. Reset one first."] = "يحتفظ المحرر بالخيارات ل {max} حرفا. أعد ضبط واحد منها أولا.",
    ["The endpoint URL was removed."] = "تمت إزالة رابط نقطة النهاية.",
    ["The endpoint answered with no text. Check the model ID."] = "ردت نقطة النهاية بدون نص. تحقق من معرف النموذج.",
    ["The endpoint did not accept your API key."] = "لم تقبل نقطة النهاية مفتاح API الخاص بك.",
    ["The endpoint did not answer. Check its address."] = "لم تستجب نقطة النهاية. تحقق من عنوانها.",
    ["The endpoint does not know that model ID."] = "نقطة النهاية لا تعرف معرف النموذج هذا.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "نقطة النهاية تحد من طلباتك. حاول مجددا بعد لحظة.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "نقطة النهاية تحد من طلباتك. انتظر نحو {seconds} ثانية، ثم حاول مجددا.",
    ["The endpoint refused the request. Check the model ID and the address."] = "رفضت نقطة النهاية الطلب. تحقق من معرف النموذج والعنوان.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "أبلغت نقطة النهاية عن خطأ من جانبها. حاول مجددا بعد لحظة.",
    ["The endpoint took too long to answer."] = "استغرقت نقطة النهاية وقتا طويلا للرد.",
    ["The example lines are too long together. Keep them under {max} characters in all."] = "أمثلة الأسطر طويلة جدا مجتمعة. اجعلها أقل من {max} حرفا في المجموع.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "لا يمكن تحرير الحقائق التي تحصل عليها الشخصيات من اللعبة، ولا القائمة القصيرة لفلاتر الأمان هنا. يدار موجه Convai من جهة Convai.",
    ["The files could not be unpacked. Try again."] = "تعذر فك ضغط الملفات. حاول مجددا.",
    ["The first line of the character text. Use {name} for the character’s name."] = "السطر الأول من نص الشخصية. استخدم {name} لاسم الشخصية.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "تم بلوغ الحد اليومي المجاني لهذا النموذج. يعاد ضبطه عند {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "تم بلوغ الحد اليومي المجاني لهذا النموذج. حاول مجددا بعد إعادة ضبطه.",
    ["The game could not verify a safe companion position."] = "تعذر على اللعبة التحقق من موضع آمن للرفيق.",
    ["The game could not verify companion body clearance."] = "تعذر على اللعبة التحقق من وجود مساحة كافية لجسد الرفيق.",
    ["The game placed this copy away from the verified ground. Invitation cancelled."] = "وضعت اللعبة هذه النسخة بعيدا عن الأرض المتحقق منها. ألغيت الدعوة.",
    ["The game placed this copy too close to someone. Invitation cancelled."] = "وضعت اللعبة هذه النسخة قريبة جدا من شخص ما. ألغيت الدعوة.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "تتعرف اللعبة على الشخص الذي تتحدث إليه من خلال اسم السجل أو اسم العرض أو كليهما. يبدو اسم السجل هكذا: Character.Rebecca أو NCA.Rebecca. أضف واحدا على الأقل.",
    ["The game version could not be read."] = "تعذر قراءة إصدار اللعبة.",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "بطاقة الرسوميات في هذا الجهاز تملك أقل من 12 GB التي يحتاجها OmniVoice بجانب اللعبة. إن تعذر تشغيله، يستخدم Pocket. اختر Pocket لتجاوز الانتظار.",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "العناوين التي تميز كل جزء من الموجه. غير الصياغة، لا الترتيب.",
    ["The hour of the day and the weather in Night City.\n\nOff: nobody is told the time or the weather, and the mod stops reading them from the game."] = "الساعة وحالة الطقس في نايت سيتي.\n\nإيقاف: لا يعرف أحد الوقت أو الطقس، ويتوقف التعديل عن قراءتهما من اللعبة.",
    ["The input the mod listens to for the talk keys and Voice activation.\n\nWindows default follows the input Windows picks. Choose another if the default never hears you, for example when a mixer app routes your microphone elsewhere.\n\nA change counts the next time the microphone opens. A missing input falls back to the default."] = "الإدخال الذي يستمع إليه التعديل لمفاتيح التحدث وتفعيل الصوت.\n\nالافتراضي في Windows يتبع الإدخال الذي يختاره Windows. اختر إدخالا آخر إن لم يسمعك الافتراضي أبدا، مثلا عندما يوجه تطبيق المزج الصوتي ميكروفونك إلى مكان آخر.\n\nيطبق التغيير في المرة التالية التي يفتح فيها الميكروفون. إن كان الإدخال مفقودا يستخدم الافتراضي.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "يبدو أن الإدخال الذي اخترته ينقل صوت الجهاز، وليس صوتك فقط. إن سمعت الشخصيات مكالماتك، فاختر ميكروفونك الحقيقي.",
    ["The installed character models could not be read."] = "تعذر قراءة نماذج الشخصيات المثبتة.",
    ["The key could not be saved."] = "تعذر حفظ المفتاح.",
    ["The key is saved, but Google Gemini is not available in your region."] = "تم حفظ المفتاح، لكن Google Gemini غير متاح في منطقتك.",
    ["The key is saved, but Google could not be reached to check it."] = "تم حفظ المفتاح، لكن تعذر الوصول إلى Google للتحقق منه.",
    ["The language of subtitles and Phone Chat. Same as speech shows what is said.\n\nAnother language is translated by one short extra request to the AI provider you chat with, alongside the voice, so the voice never waits. The original shows first.\n\nNeeds Mistral, Gemini, Custom or Local AI, not Convai."] = "لغة الترجمة النصية ودردشة الهاتف. تظهر الترجمة ما يقال بالتزامن مع الكلام.\n\nتترجم اللغة الأخرى بطلب إضافي قصير إلى مزود الذكاء الاصطناعي الذي تدردش معه، بالتوازي مع الصوت، فلا ينتظر الصوت أبدا. يظهر النص الأصلي أولا.\n\nتحتاج إلى Mistral أو Gemini أو مخصص أو Local AI، لا إلى Convai.",
    ["The last lines spoken in scenes and V’s chosen replies, so a character can pick up from what was just said.\n\nOff: they are not sent."] = "آخر الأسطر المنطوقة في المشاهد وردود V المختارة، لتتمكن الشخصية من متابعة ما قيل للتو.\n\nإيقاف: لا ترسل.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "آخر ما يقرؤه النموذج قبل أن يجيب. استخدم {name} لاسم الشخصية و{words} لطول الرد. يضيف إعداد Mature جملته الخاصة بعده.",
    ["The list will refresh in a moment."] = "ستحدث القائمة بعد لحظة.",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "أطول رد، بعدد الكلمات. يعمل مع Google Gemini و Local AI و مخصص، لا مع Convai.",
    ["The manager could not be prepared: {reason}"] = "تعذر تجهيز الإدارة: {reason}",
    ["The manager could not refresh: {reason}"] = "تعذر تحديث الإدارة: {reason}",
    ["The memory clear request could not be sent. Check the memory service before trying again."] = "تعذر إرسال طلب مسح الذاكرة. تحقق من خدمة الذاكرة قبل المحاولة مجددا.",
    ["The memory service could not confirm the clear for {target}. Review the service before choosing Forget again."] = "تعذر على خدمة الذاكرة تأكيد المسح ل {target}. راجع الخدمة قبل اختيار «نسيان» مجددا.",
    ["The memory service did not respond. Check your connection, then invite again."] = "لم تستجب خدمة الذاكرة. تحقق من اتصالك، ثم ادع مجددا.",
    ["The memory service is unavailable. Reopen this page after it reconnects."] = "خدمة الذاكرة غير متاحة. أعد فتح هذه الصفحة بعد أن تعاود الاتصال.",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "الميكروفون الذي اخترته في الإعدادات ({chosen}) غير متصل، لذلك يستخدم إدخال Windows الافتراضي: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "الميكروفون الذي اخترته في الإعدادات غير متصل، لذلك يستخدم إدخال Windows الافتراضي.",
    ["The microphone {name} sends no sound. Check your Windows input device."] = "الميكروفون {name} لا يرسل أي صوت. تحقق من جهاز الإدخال في Windows.",
    ["The model ID was removed."] = "تمت إزالة معرف النموذج.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "تعذر تحميل ربط مفاتيح التعديل. افتح المساعدة لمعرفة الخطأ.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "لم تحمل Scripts التعديل، لذلك لا يمكن تعيين أي مفتاح. افتح المساعدة لمعرفة الخطأ.",
    ["The name is too long. Keep it under {max} characters."] = "الاسم طويل جدا. اجعله أقل من {max} حرفا.",
    ["The name of the character’s record in the game files."] = "اسم سجل الشخصية في ملفات اللعبة.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "الاسم الذي تعرف به الشخصية، وتعطيه عندما يسأل أحد عن هويتها.",
    ["The name the game shows for the character."] = "الاسم الذي تعرضه اللعبة للشخصية.",
    ["The notes for this turn go"] = "ترسل ملاحظات هذه الجولة",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "القواعد المرقمة التي يقرؤها النموذج قبل كل رد. استخدم {name} لاسم الشخصية و{words} لطول رد المتحدث الذي له طول محدد.",
    ["The party could not be saved."] = "تعذر حفظ المجموعة.",
    ["The party could not finish boarding. The trip was cancelled."] = "تعذر على المجموعة إكمال الصعود. ألغيت الرحلة.",
    ["The party list could not be read. Close and reopen the manager."] = "تعذر قراءة قائمة المجموعة. أغلق الإدارة وأعد فتحها.",
    ["The port must be a number from 1 to 65535."] = "يجب أن يكون المنفذ رقما من 1 إلى 65535.",
    ["The preview waits until the problems in the form are fixed."] = "تنتظر المعاينة حتى يتم إصلاح المشكلات في النموذج.",
    ["The profile could not be assigned."] = "تعذر تعيين الملف الشخصي.",
    ["The profile could not be cleared."] = "تعذر إزالة الملف الشخصي.",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "نص الموجه كما يقرؤه النموذج لشخصية نموذجية. يتبع تعديلاتك أثناء الكتابة، قبل أن تحفظ.",
    ["The provider said: {detail}"] = "قال المزود: {detail}",
    ["The recording is distorted. Record it again, a little quieter."] = "التسجيل مشوه. سجله مجددا، بصوت أخفض قليلا.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "جودة التسجيل منخفضة جدا. استخدم {min} Hz على الأقل.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "التسجيل خافت أكثر من اللازم للنسخ. سجله بصوت أعلى، أو أقرب إلى الميكروفون.",
    ["The redscript compiler writes redscript_rCURRENT.log at {path}"] = "يكتب مصرف redscript ملف redscript_rCURRENT.log في {path}",
    ["The report could not be created. Check that the mod folder can be written to, then try again."] = "تعذر إنشاء التقرير. تحقق من إمكانية الكتابة في مجلد المود، ثم حاول مرة أخرى.",
    ["The request could not be sent. Try again."] = "تعذر إرسال الطلب. حاول مرة أخرى.",
    ["The route is blocked. Step out or try a new trip."] = "المسار مسدود. انزل من السيارة أو جرب رحلة جديدة.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "القواعد طويلة جدا معا. ابقها تحت {max} حرف في المجموع.",
    ["The same switches for a character V is only calling or texting: holocalls and Phone Chat. A companion standing beside V is still treated as in person, even when V uses the phone."] = "المفاتيح نفسها تنطبق على شخصية يتصل بها V أو يراسلها فقط، أي المكالمات الهولوغرافية ودردشة الهاتف. الرفيق الواقف بجانب V ما زال يعامل كحاضر حضوريا، حتى لو استخدم V الهاتف.",
    ["The saved clip could not be loaded."] = "تعذر تحميل المقطع المحفوظ.",
    ["The search box could not open."] = "تعذر فتح مربع البحث.",
    ["The selected companion is leaving."] = "الرفيق المحدد يغادر.",
    ["The selected companion is unavailable."] = "الرفيق المحدد غير متاح.",
    ["The server address was removed."] = "تمت إزالة عنوان الخادم.",
    ["The server answered but could not load its voice. Its window says why."] = "رد الخادم، لكنه تعذر عليه تحميل صوته. توضح نافذته السبب.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "رد الخادم، لكنه ما زال يحمل صوته. حاول مرة أخرى بعد دقيقة.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "نسخة الخادم مختلفة. استخدم مجلد الخادم والمود من الإصدار نفسه.",
    ["The server is ready."] = "الخادم جاهز.",
    ["The server refused the request."] = "رفض الخادم الطلب.",
    ["The server took too long to answer."] = "تأخر الخادم في الرد كثيرا.",
    ["The service is not available in your region."] = "الخدمة غير متاحة في منطقتك.",
    ["The service launcher writes launcher.log at {path}"] = "يكتب مشغل الخدمة ملف launcher.log في {path}",
    ["The settings are in Mod Configuration Menu, under AI Companions."] = "الإعدادات موجودة في Mod Configuration Menu ضمن AI Companions.",
    ["The settings are on the Mods screen, in the AI Companions tab."] = "الإعدادات موجودة في شاشة المودات، في تبويب AI Companions.",
    ["The settings could not be saved. Nothing was changed."] = "تعذر حفظ الإعدادات. لم يتغير شيء.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the full install zip (AI-Companions-LLM) straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "ملف إعدادات المشغل launcher.ini مفقود من red4ext/plugins/AiNpcCyberpunkMod، لذلك لا تستطيع اللعبة تشغيل خدمة المحادثة. فك ضغط ملف ZIP الكامل للتثبيت (AI-Companions-LLM) مباشرة داخل مجلد Cyberpunk 2077 من جديد (يدويا، أو بواسطة Vortex أيضا) واسمح له باستبدال الملفات، ثم أعد تشغيل اللعبة.",
    ["The setup did not finish. Try again."] = "لم يكتمل الإعداد. حاول مرة أخرى.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "لم يجتز الإعداد الاختبار على بطاقة الرسوميات لديك، لذلك لا يستطيع OmniVoice استخدامه.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "الإعداد مثبت لكنه لم يجتز الاختبار على بطاقة الرسوميات لديك. اختر إعادة التثبيت.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "لم يكتمل تسجيل الدخول. حاول مرة أخرى، أو انسخ مفتاحك من convai.com واختر لصق.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "استغرق تسجيل الدخول وقتا طويلا. اختر تسجيل الدخول عبر Convai لتجربة مرة أخرى.",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "الأغنية التي تشغل في راديو السيارة أثناء ركوب V مع الشخصية، أو في الراديو الجيبي ل V، وما يعرض على التلفاز القريب من V.\n\nإيقاف: لا يرسل ذلك، ويتوقف المود عن قراءته من اللعبة.",
    ["The speaking style is too long. Keep it under {max} characters."] = "أسلوب الكلام طويل جدا. ابقه تحت {max} حرف.",
    ["The trip exceeded its time limit."] = "تجاوزت الرحلة حدها الزمني.",
    ["The trip stopped for combat."] = "توقفت الرحلة بسبب القتال.",
    ["The trip will be stopped when you return to gameplay."] = "ستتوقف الرحلة عند عودتك إلى اللعب.",
    ["The voice V speaks with, whatever the companions use. It counts only while V’s voice is not Off.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "الصوت الذي يتحدث به V، مهما كان ما يستخدمه الرفاق. لا يحتسب إلا عندما لا يكون صوت V متوقفا.\n\nPocket: على المعالج لديك، نحو 0.2 s (بنموذج صغير خاص به إذا كان صوت الرفاق مختلفا). Voxtral: سحابي، بمفتاح Mistral الخاص بك. OmniVoice: صوت الرفاق عبر بطاقة الرسوميات، مع انتظار ثانية إضافية.",
    ["The voice files are incomplete, so the voices and the microphone cannot start. Reinstall the Full download from Nexus Mods: extract it into the Cyberpunk 2077 folder and let it replace the files, then restart the game."] = "ملفات الصوت غير مكتملة، لذلك لا يمكن تشغيل الأصوات والميكروفون. أعد تثبيت التنزيل الكامل من Nexus Mods: فك ضغطه داخل مجلد Cyberpunk 2077 واسمح له باستبدال الملفات، ثم أعد تشغيل اللعبة.",
    ["The voice files are incomplete. Reinstall the Full download from Nexus Mods."] = "ملفات الصوت غير مكتملة. أعد تثبيت التنزيل الكامل من Nexus Mods.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "لم يتم تحميل نموذج الصوت. تحقق من الصوت في الإعدادات أو اختر صوتا آخر، ثم ادع مرة أخرى.",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "الصياغات التي تضاف عند تفعيل المحتوى للبالغين. يختار المود النسخة الصريحة أو الموحية للسطر، حسب ما يسمح به النموذج المحمل، لذلك حرر النسخة التي يستخدمها نموذجك. الحقل الفارغ يحذف ذلك السطر. سطر البالغين فقط والحدود الصارمة تضاف دائما في الآخر ولا يمكن تحريرها.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "الكلام المنطوق في المقطع طويل جدا. ابقه تحت {max} حرف.",
    ["The world rules are too long. Keep them under {max} characters."] = "قواعد العالم طويلة جدا. ابقها تحت {max} حرف.",
    ["The yellow border is Windows showing a capture. Turn off Companion vision to stop it."] = "الإطار الأصفر يعني أن Windows يعرض التقاطا للشاشة. أوقف رؤية الرفيق لإيقافه.",
    ["Their quests: {done} of {total} finished"] = "مهامهم: انتهت {done} من {total}",
    ["There is no companion trip to cancel."] = "لا توجد رحلة مع رفيق لإلغائها.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "لا توجد مساحة فارغة كافية على القرص C:. حرر بعض المساحة وحاول مرة أخرى.",
    ["These Scripts {scripts} need the Runtime base {required} or newer, and your Runtime is {runtime}. Extract the full install zip (AI-Companions-LLM, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "تحتاج Scripts {scripts} إلى الإصدار الأساسي {required} من Runtime أو أحدث، و Runtime لديك هو {runtime}. فك ضغط ملف ZIP الكامل للتثبيت (AI-Companions-LLM، على Nexus Mods) داخل مجلد Cyberpunk 2077، ثم أعد تشغيل اللعبة.",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "ينضم كنسخة من النموذج الذي صنع منه. يتحدث مع Google Gemini أو Local AI أو المخصص، ومع Convai يتحدث كشخص عادي.",
    ["Things they always know"] = "أشياء يعرفها دائما",
    ["This Local AI model has no vision, so replies use only your words."] = "نموذج Local AI هذا لا يملك رؤية، لذلك تعتمد الردود على كلماتك فقط.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "لا يستطيع هذا الكمبيوتر العثور على {host}. تحقق من اتصالك بالإنترنت، ثم أعد تشغيل اللعبة.",
    ["This PC has no AMD Radeon card this setup can use."] = "لا توجد على هذا الكمبيوتر بطاقة AMD Radeon يمكن لهذا الإعداد استخدامها.",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "لا توجد على هذا الكمبيوتر بطاقة رسوميات NVIDIA، وهي مطلوبة ل OmniVoice. لن يبدأ OmniVoice هنا. اختر Pocket لسماع الأصوات.",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "هذا العنوان غير مشفر، وذلك مقبول على جهاز الكمبيوتر الخاص بك أو على شبكتك المنزلية.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "لهذه الشخصية مظهر واحد فقط في ملفات اللعبة، لذلك لا يوجد زي لاختياره.",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "تحتاج هذه الشخصية إلى Google Gemini أو Local AI أو المخصص لكي ترد.",
    ["This character speaks with a generic voice that fits the gender."] = "تتحدث هذه الشخصية بصوت عام يناسب الجنس.",
    ["This character speaks with the shipped voice."] = "تتحدث هذه الشخصية بالصوت الأصلي.",
    ["This clears the memory in use: {memory}."] = "هذا يمسح الذاكرة المستخدمة حاليا: {memory}.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "لا يستطيع هذا الكمبيوتر تحويل ذلك الملف. احفظه بصيغة WAV وحاول مرة أخرى.",
    ["This contact cannot take a holocall."] = "لا تستطيع جهة الاتصال هذه استقبال مكالمة هولوغرافية.",
    ["This contact has no companion mapping yet."] = "لا يوجد رفيق مرتبط بجهة الاتصال هذه بعد.",
    ["This copy can still follow you, but will not join conversations."] = "لا تزال هذه النسخة قادرة على متابعتك، لكنها لن تشارك في المحادثات.",
    ["This copy could not be created."] = "تعذر إنشاء هذه النسخة.",
    ["This copy could not join."] = "تعذر انضمام هذه النسخة.",
    ["This is a short report: the conversation service was not available to build the full one."] = "هذا تقرير مختصر: لم تكن خدمة المحادثة متاحة لإنشاء التقرير الكامل.",
    ["This is the first page."] = "هذه هي الصفحة الأولى.",
    ["This is the last page."] = "هذه هي الصفحة الأخيرة.",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "هذه خطتك الحالية. لتغييرها أو إلغائها، اختر «إدارة الخطة أو إلغاؤها» أدناه.",
    ["This key has no paid plan. Choose a plan below."] = "لا يملك هذا المفتاح خطة مدفوعة. اختر خطة أدناه.",
    ["This managed companion is unavailable."] = "هذا الرفيق المدار غير متاح.",
    ["This manager action is unavailable. Reopen the manager and try again."] = "إجراء الإدارة هذا غير متاح. أعد فتح الإدارة وحاول مرة أخرى.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "هذا المود مخصص للعبة {other}، ولعبتك هي {game}. احصل على ملف ZIP الكامل للتثبيت الخاص ب {game}.",
    ["This model has vision with its vision file, from {folder}/vision on Hugging Face."] = "يملك هذا النموذج رؤية بملف الرؤية الخاص به، من {folder}/vision على Hugging Face.",
    ["This mod’s scripts did not compile completely. Functions it needs that are missing: {count} ({names}). Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Also check that the Scripts are the build for game {game} and come from the same download as the Runtime, then restart the game."] = "لم يكتمل تجميع سكربتات هذا المود. الدوال اللازمة المفقودة: {count} ({names}). افتح r6/logs/redscript_rCURRENT.log. إذا ذكر الخطأ مودا آخر، فذلك المود هو المشكلة. تحقق أيضا من أن Scripts هي إصدار اللعبة {game} وأنها من التنزيل نفسه الذي جاء منه Runtime، ثم أعد تشغيل اللعبة.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware or redscript, or a game version other than {game}, can also cause it."] = "لم يتم تحميل سكربتات هذا المود. افتح r6/logs/redscript_rCURRENT.log. إذا ذكر الخطأ مودا آخر، فذلك المود هو المشكلة. وقد يسببه أيضا Codeware أو redscript القديم أو المفقود، أو إصدار للعبة غير {game}.",
    ["This must be a JSON object, for example {example}."] = "يجب أن يكون هذا كائن JSON، على سبيل المثال {example}.",
    ["This option does not get the Mature layer."] = "لا يحصل هذا الخيار على طبقة المحتوى للبالغين.",
    ["This setting must be on or off."] = "يجب أن يكون هذا الإعداد مفعلا أو متوقفا.",
    ["This text cannot be empty."] = "لا يمكن أن يكون هذا النص فارغا.",
    ["This text is too long. Keep it under {max} characters."] = "هذا النص طويل جدا. ابقه تحت {max} حرف.",
    ["Time and weather"] = "الوقت والطقس",
    ["Time since last talk"] = "الوقت منذ آخر محادثة",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "استنفدت جولات Convai اليوم.\nتتجدد عند {time}. جرب Local AI (غير محدود) أو Google Gemini (بمفتاحك الخاص).",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "استنفدت جولات Convai اليوم.\nجرب Local AI (غير محدود) أو Google Gemini (بمفتاحك الخاص).",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "استنفدت {limit} من جولات Convai اليوم.\nتتجدد عند {time}. جرب Local AI (غير محدود) أو Google Gemini (بمفتاحك الخاص).",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "استنفدت {limit} من جولات Convai اليوم.\nجرب Local AI (غير محدود) أو Google Gemini (بمفتاحك الخاص).",
    ["Together"] = "معا",
    ["Tone line"] = "سطر النبرة",
    ["Too many display names. Keep {max} or fewer."] = "أسماء عرض كثيرة جدا. ابق {max} أو أقل.",
    ["Too many example lines. Keep {max} or fewer."] = "أسطر أمثلة كثيرة جدا. ابق {max} أو أقل.",
    ["Too many keys. Keep {max} or fewer."] = "مفاتيح كثيرة جدا. ابق {max} أو أقل.",
    ["Too many memories. Keep {max} or fewer."] = "ذكريات كثيرة جدا. ابق {max} أو أقل.",
    ["Too many record names. Keep {max} or fewer."] = "أسماء سجلات كثيرة جدا. ابق {max} أو أقل.",
    ["Too many rules. Keep {max} or fewer."] = "قواعد كثيرة جدا. ابق {max} أو أقل.",
    ["Too many stop texts. Keep {max} or fewer."] = "نصوص إيقاف كثيرة جدا. ابق {max} أو أقل.",
    ["Top K"] = "Top K",
    ["Top P"] = "Top P",
    ["Trench coat"] = "معطف خندق",
    ["Trip cancelled from Companion Manager."] = "تم إلغاء الرحلة من إدارة الرفاق.",
    ["Trip cancelled."] = "تم إلغاء الرحلة.",
    ["Trusted"] = "موثوق",
    ["Turkish"] = "التركية",
    ["Turn chat off"] = "أوقف الدردشة",
    ["Turn chat on"] = "فعل الدردشة",
    ["Turn off"] = "أوقف",
    ["Turn on"] = "فعل",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "يفعل حزمة المحتوى {name} أو يوقفها. تغير الحزمة طريقة كلام الشخصيات. تعمل تغييرات التعليمات الخاصة بها مع Google Gemini و Local AI والمخصص. على Convai تطبق قواعد العالم الخاصة بها وشخصيات Convai الخاصة بها. يسري التبديل من الرد التالي، والأسماء الجديدة بعد إعادة التشغيل.",
    ["Two options fit. Say its number."] = "يناسب خياران. قل الرقم الخاص بالخيار.",
    ["Type a message first."] = "اكتب رسالة أولا.",
    ["Type a name to search"] = "اكتب اسما للبحث",
    ["No characters to chat with yet. Close the phone and open it again in a moment."] = "لا توجد شخصيات للدردشة معها بعد. أغلق الهاتف ثم افتحه مرة أخرى بعد قليل.",
    ["Type part of a name"] = "اكتب جزءا من الاسم",
    ["Opens a text box over the game. Type the new name and press Enter. Esc leaves the name as it is."] = "يفتح مربع نص فوق اللعبة. اكتب الاسم الجديد واضغط Enter. يترك Esc الاسم كما هو.",
    ["Type the words said in the clip, at least {min} characters."] = "اكتب الكلام المقول في المقطع، بما لا يقل عن {min} حرف.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "اكتب ما يقوله المقطع كما ينطق. يحتاجه OmniVoice لنسخ الصوت.",
    ["Type your message to the character."] = "اكتب رسالتك إلى الشخصية.",
    ["Typed and spoken lines"] = "أسطر مكتوبة ومنطوقة",
    ["Typed lines"] = "أسطر مكتوبة",
    ["UP / DOWN: SELECT    LEFT / RIGHT: PAGE    TAB: SEARCH    ENTER: ACTION    F5: CLOSE"] = "أعلى / أسفل: تحديد    يسار / يمين: صفحة    TAB: بحث    ENTER: إجراء    F5: إغلاق",
    ["Ukrainian"] = "الأوكرانية",
    ["Unable to send the message. Your draft has been kept."] = "تعذر إرسال الرسالة. تم الاحتفاظ بمسودتك.",
    ["Unavailable"] = "غير متاح",
    ["Uncensored model"] = "نموذج بلا رقابة",
    ["Unknown"] = "غير معروف",
    ["Unknown setting: {setting}"] = "إعداد غير معروف: {setting}",
    ["Unnamed model {index}"] = "نموذج بلا اسم {index}",
    ["Unpacking…"] = "يجري فك الضغط…",
    ["Unsaved changes"] = "تغييرات غير محفوظة",
    ["Unselect"] = "إلغاء الاختيار",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "إلى أن تختار نموذجا، يحمل Local AI أكبر نموذج يتسع في ذاكرة الرسوميات الحرة لديك.\n\nنموذج واحد في كل مرة، ويسري التغيير عند التحميل التالي. النموذج المفقود أو الكبير جدا أو المعطوب يستبدل بأكبر نموذج يتسع، مع إشعار واحد.",
    ["Up arrow"] = "السهم لأعلى",
    ["Update"] = "تحديث",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "حدث Mod Configuration Menu إلى 0.10.5 أو أحدث، أو ثبت Native Settings UI",
    ["Update with current party"] = "حدث مع المجموعة الحالية",
    ["Updating selection"] = "يجري تحديث الاختيار",
    ["Use Confirm or Cancel for the current memory request."] = "استخدم تأكيد أو إلغاء لطلب الذاكرة الحالي.",
    ["Use a number from {min} to {max}."] = "استخدم رقما من {min} إلى {max}.",
    ["Use profile"] = "استخدم الملف",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "استخدم خانة أطول رد لتحديد طول الرد، لا «{name}».",
    ["Use the address only: no user name, no path, no #."] = "أدخل العنوان فقط: بدون اسم مستخدم، وبدون مسار، وبدون #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "استخدم العنوان الذي تعرضه نافذة الخادم، مثل 192.168.1.20:8765، بدون https://.",
    ["Use the base URL only: no password, query or #."] = "استخدم عنوان URL الأساسي فقط: بدون كلمة مرور أو استعلام أو #.",
    ["Use the character I’m facing"] = "استخدم الشخصية التي أمامي",
    ["Use this conversation profile"] = "استخدم ملف المحادثة هذا",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "استخدم من {min} إلى {max} ثانية لشخص واحد يتحدث بوضوح، بدون موسيقى أو أصوات أخرى. من {goodMin} إلى {goodMax} ثانية تعطي أفضل نسخة. الصيغ: WAV أو MP3 أو OGG أو FLAC.",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "يستخدم للأسطر المكتوبة ل V، وتنسخه Pocket وOmniVoice وصوت Voxtral السحابي.",
    ["Using {model}"] = "يجري استخدام {model}",
    ["Usual look"] = "المظهر المعتاد",
    ["V (female voice)"] = "V (صوت أنثوي)",
    ["V (male voice)"] = "V (صوت ذكوري)",
    ["V changed seats or vehicles."] = "غير V المقعد أو المركبة.",
    ["V left the passenger seat."] = "غادر V مقعد الراكب.",
    ["V or a scene has taken vehicle control."] = "أخذ V أو أحد المشاهد التحكم في المركبة.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "يتحدث V بصوت مود الأصوات الخاص ب V المثبت لديك، أو بالصوت الأصلي ل V.",
    ["Valentino look"] = "مظهر Valentino",
    ["Valentino look, collar open"] = "مظهر Valentino، والياقة مفتوحة",
    ["Vehicle exit workspot state is unavailable."] = "حالة نقطة عمل الخروج من المركبة غير متاحة.",
    ["Vehicle information became unavailable."] = "أصبحت معلومات المركبة غير متاحة.",
    ["Vehicle information is not ready."] = "معلومات المركبة غير جاهزة.",
    ["Version {version}."] = "الإصدار {version}.",
    ["Version {version}. The mod is tested on {game} only, so some things may not work."] = "الإصدار {version}. تم اختبار المود على {game} فقط، لذلك قد لا تعمل بعض الأشياء.",
    ["Version {version}. These files are the mod build for game {build}. Extract the full install zip made for game {game}, from the mod’s Nexus Mods page, into the Cyberpunk 2077 folder, then restart the game."] = "الإصدار {version}. هذه الملفات هي بناء المود للعبة {build}. فك ضغط ملف ZIP الكامل للتثبيت المخصص للعبة {game}، من صفحة المود على Nexus Mods، داخل مجلد Cyberpunk 2077، ثم أعد تشغيل اللعبة.",
    ["Very short: up to about {words} words"] = "قصير جدا: حتى نحو {words} كلمة",
    ["Vest"] = "صدرية",
    ["Vest and rucksack"] = "صدرية وحقيبة ظهر",
    ["Vietnamese"] = "الفيتنامية",
    ["View"] = "عرض",
    ["Voice"] = "الصوت",
    ["Voice AI and microphone"] = "الصوت والميكروفون",
    ["Voice activation"] = "التنشيط الصوتي",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "تعذر على التنشيط الصوتي فتح الميكروفون. تحقق من جهاز الإدخال في Windows.",
    ["Voice conversation failed. Check your microphone and try again."] = "فشلت المحادثة الصوتية. تحقق من الميكروفون وحاول مرة أخرى.",
    ["Voice files"] = "ملفات الصوت",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "تعذر وصول الإدخال الصوتي إلى Convai. اضغط مطولا على مفتاح الصوت مرة أخرى، أو اكتب.",
    ["Voice input in this language needs the optional Microphone pack from the mod page. Typing works in any language."] = "الإدخال الصوتي بهذه اللغة يحتاج إلى حزمة الميكروفون الاختيارية من صفحة المود. الكتابة تعمل بأي لغة.",
    ["Voice input only understands English for now. Typing works in any language."] = "الإدخال الصوتي يفهم الإنجليزية فقط حاليا. الكتابة تعمل بأي لغة.",
    ["Voice language"] = "لغة الصوت",
    ["Voice: {voice}"] = "الصوت: {voice}",
    ["Vortex. Install the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say. Install the full install zip as one mod and update that mod with each new full install zip."] = "Vortex. ثبت الحزم الاختيارية يدويا داخل مجلد Cyberpunk 2077، كما تقول خطوات التثبيت. ثبت ملف ZIP الكامل للتثبيت كمود واحد، وحدث هذا المود مع كل ملف ZIP كامل جديد.",
    ["Voxtral is not used with Mature content."] = "لا يستخدم Voxtral مع المحتوى للبالغين.",
    ["Voxtral key"] = "مفتاح Voxtral",
    ["Voxtral speaks with your Mistral API key. Copy it first, then press Add. It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nIt is the same key as the Mistral API key on the AI provider page. A Mistral key saved there is set here already."] = "يتحدث Voxtral بمفتاح Mistral API الخاص بك. انسخه أولا، ثم اضغط إضافة. يقرأ من الحافظة مرة واحدة، ويتحقق منه Mistral ويحفظ على هذا الكمبيوتر.\n\nهو المفتاح نفسه الموجود في Mistral API في صفحة مزود الذكاء الاصطناعي. مفتاح Mistral المحفوظ هناك يكون مضبوطا هنا بالفعل.",
    ["Voxtral stops speaking. Replies show as text until a key is saved."] = "يتوقف Voxtral عن الكلام. تظهر الردود كنص حتى يحفظ مفتاح.",
    ["Voxtral · Mistral cloud"] = "Voxtral · سحابة Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · يحتاج مفتاح Mistral",
    ["Voxtral · not with Mature"] = "Voxtral · لا يعمل مع البالغين",
    ["V’s gear and clothes"] = "معدات وملابس V",
    ["V’s gender and lifepath"] = "جنس V ومسار حياته",
    ["V’s health, the police heat on V, and the last fight V was in.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "صحة V، وملاحقة الشرطة ل V، وآخر قتال شارك فيه V.\n\nإيقاف: لا يرسل شيء من ذلك، ويتوقف المود عن قراءته من اللعبة.",
    ["V’s money"] = "نقود V",
    ["V’s tracked quest and its objectives, the jobs V has open and the journal history.\n\nWhat each character knows about your story stays on.\n\nOff: none of this is sent. The mod stops scanning the journal for it, unless Johnny’s remarks are on."] = "المهمة المتتبعة ل V وأهدافها، والمهام المفتوحة لدى V، وسجل اليوميات.\n\nما تعرفه كل شخصية عن قصتك يبقى مفعلا.\n\nإيقاف: لا يرسل شيء من ذلك. يتوقف المود عن فحص اليوميات بحثا عن ذلك، إلا إذا كانت ملاحظات جوني مفعلة.",
    ["V’s voice"] = "صوت V",
    ["V’s voice engine"] = "محرك صوت V",
    ["V’s voice stays on Voxtral and is skipped until a key is saved."] = "يبقى صوت V على Voxtral ويتخطى حتى يحفظ مفتاح.",
    ["V’s voice switches from OmniVoice to Pocket."] = "يتحول صوت V من OmniVoice إلى Pocket.",
    ["V’s voice volume (%)"] = "مستوى صوت V (%)",
    ["Wait for the current vehicle activity to finish."] = "انتظر حتى تنتهي فعالية المركبة الحالية.",
    ["Wait for your car to stop."] = "انتظر حتى تتوقف سيارتك.",
    ["Wait for your previous reply before sending another message."] = "انتظر رد الشخصية السابق قبل إرسال رسالة أخرى.",
    ["Wait for your summoned car to arrive."] = "انتظر وصول سيارتك التي استدعيتها.",
    ["Waiting for current vehicle information."] = "في انتظار معلومات المركبة الحالية.",
    ["Waiting for party to board"] = "في انتظار صعود المجموعة",
    ["Waiting for the companion to release the driver seat."] = "في انتظار أن يحرر الرفيق مقعد السائق.",
    ["Waiting for the conversation service."] = "في انتظار خدمة المحادثة.",
    ["Waiting for the conversation to end"] = "في انتظار انتهاء المحادثة",
    ["Waiting for the endpoint to answer…"] = "في انتظار رد نقطة النهاية…",
    ["Waiting for the existing companion after vehicle exit."] = "في انتظار الرفيق الحالي بعد النزول من المركبة.",
    ["Waiting for the native occupant slot to release."] = "في انتظار أن تحرر اللعبة مقعد الراكب.",
    ["Waiting for the native vehicle exit animation to finish."] = "في انتظار انتهاء حركة النزول من المركبة الأصلية.",
    ["Waiting for the native vehicle exit to finish."] = "في انتظار أن تنتهي اللعبة من النزول من المركبة.",
    ["Waiting for the native vehicle mount to release."] = "في انتظار أن تحرر اللعبة ربط المركبة.",
    ["Waiting for the native vehicle transition to finish."] = "في انتظار أن تنتهي اللعبة من انتقال المركبة.",
    ["Waiting for the result of clearing memories for {target}. Reopen this page after the memory service reconnects."] = "في انتظار نتيجة مسح الذكريات ل {target}. أعد فتح هذه الصفحة بعد أن تعود خدمة الذاكرة إلى الاتصال.",
    ["Waiting for the server to answer…"] = "في انتظار رد الخادم…",
    ["Waiting for walking ownership to resume."] = "في انتظار استعادة التحكم في المشي.",
    ["Waiting for you to board"] = "في انتظار صعودك",
    ["Waiting for you to step out"] = "في انتظار نزولك",
    ["Waiting for your companion to settle before boarding."] = "في انتظار أن يستقر رفيقك قبل الصعود.",
    ["Waiting for your passenger seat to be released."] = "في انتظار تحرير مقعد الراكب لديك.",
    ["Waiting for your previous message to finish."] = "في انتظار انتهاء رسالتك السابقة.",
    ["Walk"] = "المشي",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "المشي: تظهر خارج نطاق نظرك وتمشي نحوك.\n\nالسيارة: عندما يكون الطريق قريبا تدخل بالسيارة، وتتوقف على الطريق، ثم تنزل وتمشي المسافة المتبقية. بدون طريق تمشي. تبقى السيارة قريبة للرحلة، وتزال عندما تغادر مجموعتك، أو عندما تبتعدان كثيرا عنها.",
    ["Walking commands did not release in time."] = "لم تتحرر أوامر المشي في الوقت المناسب.",
    ["Warming up"] = "في طور التحضير",
    ["Warmth: {points}"] = "الدفء: {points}",
    ["Watson Northside"] = "شمال واتسون",
    ["Westbrook Japantown"] = "حي اليابانيين في وستبروك",
    ["What V wears and carries: clothes, weapons and cyberware that can be seen.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "ما يرتديه V ويحمله: الملابس والأسلحة والسايبروير المرئي.\n\nإيقاف: لا يرسل ذلك، ويتوقف المود عن قراءته من اللعبة.",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "ما تخبر به اللعبة كل شخصية عن هذه اللحظة. تذكره الشخصية فقط عندما يناسب الحديث.\n\nالنوع المتوقف يحذف من كل مزود للمحادثة (Convai، Google Gemini، Local AI والمخصص).",
    ["What they do now and then while they stand beside you."] = "ما يفعلونه بين حين وآخر وهم واقفون بجانبك.",
    ["What to do"] = "ما يجب فعله",
    ["When she arrives"] = "عندما تصل",
    ["When something in the mod goes wrong, a short report goes to the developer.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name.\n\nIt holds the error, versions, settings, PC details (graphics card, processor, Windows, security software, drive, screen), mod names, setup check, reply timings and nearby log lines (for setup and script errors also the Cyber Engine Tweaks log)."] = "عند حدوث خطأ في المود، يرسل تقرير قصير إلى المطور.\n\nلا يحتوي أبدا على المفاتيح، ولا على ما تقوله أنت أو الشخصيات، ولا على الذكريات أو الصوت أو اسم مستخدم Windows.\n\nيحتوي على الخطأ والإصدارات والإعدادات وتفاصيل الكمبيوتر (بطاقة الرسوميات والمعالج وWindows وبرنامج الحماية والقرص والشاشة) وأسماء المودات ونتيجة فحص الإعداد وأزمنة الرد وسطور السجل القريبة (ولأخطاء الإعداد والسكربت سجل Cyber Engine Tweaks أيضا).",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "عندما يكون اثنان أو أكثر من رفاق السكن معك في المنزل، يتحدثون مع بعضهم بين حين وآخر.",
    ["When you are close and a character’s own quests are done, they can start a short story of their own. It plays out in talks, texts and calls, and some use Eddies with characters and Immersive invitations.\n\nNeeds Character bonds. Own characters and channels only, never the game’s own scenes or quests. Off by default."] = "عندما تكون قريبا من شخصية وتكون مهامها الخاصة قد انتهت، يمكنها أن تبدأ قصة قصيرة خاصة بها. تجري أحداثها في المحادثات والرسائل والمكالمات، ويستخدم بعضها إيدي مع الشخصيات ودعوات Immersive.\n\nتحتاج إلى علاقات الشخصيات. للشخصيات والقنوات الخاصة فقط، وليس أبدا مشاهد اللعبة أو مهامها. متوقف افتراضيا.",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "عندما تطلب منها أن تأتي إلى نقطة المسار ويكون دبوس الخريطة محددا، تذهب إلى هناك وتخبرك بذلك. إيقاف: تأتي دائما إلى حيث أنت.",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The vision Convai has of what V sees, and an add-on’s own text, are not affected."] = "مكان V: الحي، وشقة V أو المكان المذكور عندما تذكر اللعبة ذلك.\n\nإيقاف: لا تعرف الشخصيات أين أنت، ويتوقف المود عن قراءة ذلك من اللعبة. لا تتأثر رؤية Convai لما يراه V ولا نص الإضافة نفسه.",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "مكان سكن الشخصية عندما تقول إن بإمكانها البقاء دون تسمية شقة، وأنت لست في إحدى شققك.\n\nاسألني: تسأل الشخصية أي شقة. وإلا فستأخذ الشقة التي تختارها هنا. تعرض القائمة الشقق التي تملكها فقط.",
    ["Where some notes go in the prompt."] = "أين توضع بعض الملاحظات في الموجه.",
    ["Where the logs are"] = "مكان السجلات",
    ["Whether V is a woman or a man, and V’s lifepath: Nomad, Street Kid or Corpo.\n\nOff: it is not sent with a turn, and the mod stops reading it for that. Your story’s own facts may still reflect your lifepath."] = "هل V امرأة أم رجل، ومسار حياة V: الرحالة، أو طفل الشوارع، أو موظف الشركة.\n\nإيقاف: لا يرسل مع كل جولة محادثة، ويتوقف المود عن قراءته لذلك. قد تعكس وقائع قصتك مسار حياتك.",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "هل الخادم قيد الاستخدام الآن. يتم فحصه عند الحاجة إلى صوت، وبعد الفشل يتم فحصه مجددا كل بضع ثوان، ولا يتم فحصه إطلاقا أثناء اللعب.",
    ["While this is on, they do not answer you and never join a group chat. Untick it to talk to them again."] = "طالما هذا الخيار مفعل، لا يردون عليك ولا ينضمون إلى الدردشة الجماعية أبدا. أزل العلامة للتحدث معهم مجددا.",
    ["Who else is with V, whether V is on foot or in a vehicle, and what a companion is doing beside V.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "من الموجود مع V، وهل V مشيا على الأقدام أم داخل مركبة، وماذا يفعل الرفيق إلى جانب V.\n\nإيقاف: لا يتم إرسال شيء من ذلك، ويتوقف المود عن قراءته من اللعبة.",
    ["Who this character is, what they know and how they look. A long bio makes replies slower, so keep it tight."] = "من هذه الشخصية، وماذا تعرف، وكيف تبدو. السيرة الطويلة تبطئ الردود، لذا اجعلها مختصرة.",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "من هذه الشخصية، وماذا تعرف، وكيف تبدو. الأفضل أن تكتبها بصيغة «أنا …». السيرة الطويلة تبطئ الردود، لذا اجعلها مختصرة.",
    ["Who writes the replies."] = "من يكتب الردود.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "من يكتب ردود رفاقك. ينتظر التغيير حتى لا تكون هناك محادثة جارية.\n\nالمستوى المجاني من Convai لا يحتاج إلى إعداد، ويعطي ردودا أفضل. مفتاح Convai API يستخدم مفتاحك الخاص. يستخدم Google Gemini مفتاحك المجاني الخاص، وتبقى الذاكرة على هذا الكمبيوتر.\n\nمع Google Gemini أو Local AI أو مخصص، يستخدم النظام صوتا محليا بدلا من صوت Convai السحابي. يتم التعرف على الكلام على هذا الكمبيوتر، لذلك يعمل مفتاح الصوت.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "من يكتب ردود رفاقك. ينتظر التغيير حتى لا تكون هناك محادثة جارية.\n\nالمستوى المجاني من Convai لا يحتاج إلى إعداد، ويعطي ردودا أفضل. مفتاح Convai API يستخدم مفتاحك الخاص. يستخدم Google Gemini مفتاحك المجاني الخاص، وتبقى الذاكرة على هذا الكمبيوتر.\n\nمع Google Gemini أو Local AI أو مخصص، يستخدم النظام صوتا محليا بدلا من صوت Convai السحابي. التعرف على الكلام بمفتاح الصوت غير متاح مع هذه الخيارات بعد، لذلك اكتب رسائلك.",
    ["Who you can talk to and what they know."] = "مع من يمكنك التحدث وماذا يعرفون.",
    ["Whose memories"] = "ذكريات من",
    ["Windows (Smart App Control or an Application Control policy) blocks the files of the model server, so Local AI cannot run on this PC. Choose a cloud conversation provider in Settings."] = "يمنع Windows (Smart App Control أو سياسة Application Control) ملفات خادم النموذج، لذلك لا يمكن تشغيل Local AI على هذا الكمبيوتر. اختر مزود محادثة سحابي في الإعدادات.",
    ["Windows (Smart App Control or an Application Control policy) blocks the files of the voice, so Pocket cannot run on this PC. Choose a cloud voice (Voxtral) in Settings."] = "يمنع Windows (Smart App Control أو سياسة Application Control) ملفات الصوت، لذلك لا يمكن تشغيل Pocket على هذا الكمبيوتر. اختر صوتا سحابيا (Voxtral) في الإعدادات.",
    ["Windows default"] = "افتراضي Windows",
    ["Windows ran out of memory for the voice. A larger paging file or closing other apps helps."] = "نفدت ذاكرة Windows المخصصة للصوت. يساعد توسيع ملف الصفحات أو إغلاق التطبيقات الأخرى.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "لم يسمح Windows للعبة ببدء خدمة المحادثة (الخطأ {error}). قد يمنع برنامج أمني node.exe في red4ext/plugins/AiNpcCyberpunkMod/app/node: اسمح له، ثم أعد تشغيل اللعبة.",
    ["With a mod manager: remove the old Scripts and Runtime mods, then install the full install zip as one mod."] = "مع مدير المودات: أزل المودين القديمين Scripts و Runtime، ثم ثبت ملف ZIP الكامل للتثبيت كمود واحد.",
    ["Without the coat"] = "بدون المعطف",
    ["Word bank"] = "بنك الكلمات",
