    ["You have changes that are not saved. Leave without saving?"] = "لديك تغييرات غير محفوظة. هل تغادر دون حفظ؟",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "لقد أنشأت أقصى عدد من الشخصيات يحتفظ به المحرر ({max}). احذف واحدة أولا.",
    ["You have switched off as many people as the editor keeps ({max}). Switch one back on first."] = "لقد أوقفت أقصى عدد من الأشخاص يحتفظ به المحرر ({max}). أعد تفعيل واحد أولا.",
    ["You have too many favorites. Remove one first."] = "لديك عدد كبير جدا من المفضلات. أزل واحدة أولا.",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "استنفدت حصة اليوم البالغة {limit} جولة، وتعود عند {time}. لمواصلة الحديث الآن، اختر Local AI (بلا حد) أو Google Gemini (بمفتاحك الخاص).",
    ["You moved away from the car. The trip was cancelled."] = "ابتعدت عن السيارة. تم إلغاء الرحلة.",
    ["You: {text}"] = "أنت: {text}",
    ["Your Convai plan"] = "خطتك في Convai",
    ["Your Convai plan cannot hold the memory these conversations need. Free a memory user in your Convai account or use another key."] = "خطتك في Convai لا تتسع للذاكرة التي تحتاجها هذه المحادثات. حرر مستخدم ذاكرة في حسابك في Convai أو استخدم مفتاحا آخر.",
    ["Your Convai plan has no room for conversation memory, so companions will not remember past talks."] = "لا تتسع خطتك في Convai لذاكرة المحادثات، لذلك لن يتذكر الرفاق الأحاديث السابقة.",
    ["Your Convai plan is active."] = "خطتك في Convai نشطة.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "خطتك في Convai نشطة. تستخدم المحادثات الآن مفتاح Convai API الخاص بك.",
    ["Your Custom endpoint does not accept vision, so replies use only your words."] = "نقطة الوصول المخصصة بك لا تقبل الرؤية، لذلك تعتمد الردود على كلماتك وحدها.",
    ["Your Custom models and APIs"] = "نماذجك وواجهات API المخصصة",
    ["Your browser could not be opened."] = "تعذر فتح المتصفح.",
    ["Your car has no free passenger seat for V."] = "ليس في سيارتك مقعد ركاب فارغ ل V.",
    ["Your changes work with every conversation option. With Convai they are sent as notes with each reply."] = "تعمل تغييراتك مع كل خيارات المحادثة. مع Convai يتم إرسالها كملاحظات مع كل رد.",
    ["Your character"] = "شخصيتك",
    ["Your characters"] = "شخصياتك",
    ["Your companion is driving to the selected waypoint."] = "رفيقك يقود السيارة إلى نقطة الطريق المحددة.",
