    ["{name}: {reason}"] = "{name}: {reason}",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "لدى {other} ملف بالفعل في المود، وهذا الملف له الأولوية دائما. استخدم سجلا أو اسما آخر.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} موجود في مجلد أعمق بمستوى واحد، في {folder}. أعد تشغيل اللعبة وسينقله المود إلى مكانه. إذا بقي هناك بعد ذلك، انقل مجلد red4ext الموجود داخله إلى مجلد Cyberpunk 2077.",
    ["{party}: inviting {names}."] = "{party}: جاري دعوة {names}.",
    ["{part}, for models that allow explicit sex"] = "{part}، للنماذج التي تسمح بالمحتوى الجنسي الصريح.",
    ["{part}, for models that keep sex suggestive"] = "{part}، للنماذج التي تبقي الإيحاء الجنسي فقط.",
    ["{plan}, {price} a month"] = "{plan}، {price} شهريا",
    ["{plan}, {price} a year"] = "{plan}، {price} سنويا",
    ["{points} of {needed} points to level {to}"] = "{points} من {needed} نقطة للوصول إلى المستوى {to}",
    ["{requested} is not ready yet. Companions are using {voice} for now."] = "{requested} غير جاهز بعد. يستخدم الرفاق {voice} حاليا.",
    ["{requested} is unavailable right now. Replies show as text until it is back."] = "{requested} غير متاح الآن. تظهر الردود كنص إلى أن يعود.",
    ["{requested} is unavailable. Companions are using {voice} instead."] = "{requested} غير متاح. يستخدم الرفاق {voice} بدلا منه.",
    ["{title} (finished)"] = "{title} (مكتمل)",
    ["{title}: {label}"] = "{title}: {label}",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: يجب الإعداد أولا",
    ["{voice} · needs 12 GB card"] = "{voice} · يحتاج إلى بطاقة 12 GB",
    ["{voice} · needs Inworld key"] = "{voice} · يحتاج إلى مفتاح Inworld",
    ["{voice} · needs Mistral key"] = "{voice} · يحتاج إلى مفتاح Mistral",
    ["{voice} · needs NVIDIA card"] = "{voice} · يحتاج إلى بطاقة NVIDIA",
    ["{voice} · needs Omni pack"] = "{voice} · يحتاج إلى حزمة Omni",
    ["“{name}” has its own setting in this form. Use that instead."] = "لدى «{name}» إعداد خاص به في هذا النموذج. استخدمه بدلا منه.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "«{name}» ليس اسم مفتاح صالحا. استخدم حروفا وأرقاما وشرطات سفلية.",
    ["“{name}” is set by the mod and cannot be changed here."] = "«{name}» يحدده المود ولا يمكن تغييره هنا.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "«{name}» يحتاج إلى رقم أو نص أو صح أو خطأ، أو قائمة من هذه القيم.",
    ["A kiss with your romance partner, or with someone whose bond has reached romance. Chosen in their reply, or ask for it.\n\nWorks with your copies, the game’s own characters and characters from other spawners. Never in a fight, ride, scene, menu or scripted dialogue. On by default."] = "قبلة مع شريك علاقتك الرومانسية، أو مع شخص بلغت علاقتك به مستوى الرومانسية. يختار في رده، أو اطلبه.\n\nيعمل مع نسخك، وشخصيات اللعبة الأصلية، والشخصيات القادمة من إضافات أخرى. لا يحدث أبدا أثناء القتال أو الركوب أو المشاهد أو القوائم أو الحوارات المبرمجة. مفعل افتراضيا.",
    ["Bonds are not kept while Character bonds is off, so nobody is listed here. Turn it on in Companions and Night City."] = "لا تحفظ الروابط عند إيقاف روابط الشخصيات، لذلك لا يظهر أحد هنا. فعله من قسم المرافقون وNight City.",
    ["Borrow, lend, give and repay eddies by talking to named party members, visitors and housemates, including safely controlled characters from other spawners. Each decides from their story and bond with you.\n\nMoney moves when the reply agrees. Your balance and debts are checked again before payment. Game-placed characters only talk about it. Off by default."] = "يمكنك استعارة الإيدي وإقراضه ومنحه وسداده من خلال الحديث مع أعضاء الفريق المسمين والزوار وشركاء السكن، بما فيهم الشخصيات الخاضعة للتحكم الآمن من إضافات أخرى. يقرر كل منهم بناء على قصته وروابطه معك.\n\nينتقل المال عندما يوافق الرد. يعاد التحقق من رصيدك وديونك قبل الدفع. الشخصيات المتواجدة في اللعبة أصلا تتحدث عن الأمر فقط. معطل افتراضيا.",
    ["Companions and Night City"] = "المرافقون وNight City",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off on the Content packs page in the game."] = "تضيف حزم المحتوى قواعد بعد قواعدك. لا يمكنك تعديلها هنا: أوقف الحزمة من صفحة حزم المحتوى داخل اللعبة.",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI on the AI provider page."] = "تعذر على Convai تسجيل الدخول. حاول مرة أخرى بعد لحظات، أو اختر Google Gemini أو Local AI من صفحة مزود الذكاء الاصطناعي.",
    ["Convai did not accept your API key. Check it on the AI provider page."] = "لم يقبل Convai مفتاح API الخاص بك. تحقق منه في صفحة مزود الذكاء الاصطناعي.",
    ["Convai has not confirmed your plan yet. Check it on the AI provider page, Convai paid tier."] = "لم يؤكد Convai خطتك بعد. تحقق منها في صفحة مزود الذكاء الاصطناعي، ضمن المستوى المدفوع من Convai.",
    ["Custom is not set up, so Convai is used. Add its URL and model ID in AI provider."] = "الخيار المخصص غير معد، لذلك يستخدم Convai. أضف عنوانه ومعرف النموذج في مزود الذكاء الاصطناعي.",
    ["Error reports go to the developer. Turn them off on the Privacy and help page."] = "ترسل تقارير الأخطاء إلى المطور. أوقفها من صفحة الخصوصية والمساعدة.",
    ["Google Gemini has no key yet, so Convai is used. Add your key on the AI provider page."] = "لا يوجد مفتاح لـ Google Gemini بعد، لذلك يستخدم Convai. أضف مفتاحك في صفحة مزود الذكاء الاصطناعي.",
    ["Johnny in your head is off. Turn it on from the Conversations page."] = "جوني في رأسك متوقف. فعله من صفحة المحادثات.",
    ["Life with your party, and how the world reacts to V."] = "الحياة مع فريقك، وكيف يتفاعل العالم مع V.",
    ["Local AI could not start. Check Local AI on the AI provider page."] = "تعذر تشغيل Local AI. تحقق منه في صفحة مزود الذكاء الاصطناعي.",
    ["Mature content is off: the chosen model has no Mature version. Install the Mature pack to use it."] = "المحتوى الناضج متوقف: النموذج المختار لا يملك نسخة Mature. ثبت حزمة Mature لاستخدامه.",
    ["Mature content is on: the Local AI model in use is a Mature model."] = "المحتوى الناضج مفعل: نموذج Local AI المستخدم حاليا نموذج ناضج.",
    ["Mistral did not accept your key. Check it on the AI provider page."] = "لم يقبل Mistral مفتاحك. تحقق منه في صفحة مزود الذكاء الاصطناعي.",
    ["Mistral has no key yet, so Convai is used. Add your key on the AI provider page."] = "لا يوجد مفتاح لـ Mistral بعد، لذلك يستخدم Convai. أضف مفتاحك في صفحة مزود الذكاء الاصطناعي.",
    ["Nearby companions, including characters from other spawners, sometimes speak at calm moments or after a scene. Up to three can chat, and you can join by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often: about 6. Counts calm play. With Johnny too, rates add up and they take turns."] = "قد يتحدث المرافقون القريبون، بمن فيهم شخصيات من إضافات أخرى، أحيانا في لحظات الهدوء أو بعد مشهد. يمكن لثلاثة منهم كحد أقصى أن يشاركوا في الحديث، ويمكنك الانضمام بالكلام. لا يحدث ذلك أبدا أثناء القتال أو المشاهد أو المكالمات أو القوائم.\n\nنادرا: نحو مرتين في الساعة. عادة: نحو أربع مرات. غالبا: نحو ست مرات. تحتسب لحظات اللعب الهادئ فقط. ومع جوني أيضا، تتراكم المعدلات ويتناوبون على الحديث.",
    ["No Local AI pack found. Extract the pack zip (Local AI or Mature) into your Cyberpunk 2077 folder, the one with bin, archive and r6, and not into a new folder named after the zip. Its files belong in red4ext/plugins/AiNpcCyberpunkMod/app/local-ai."] = "لم يعثر على حزمة Local AI. فك ضغط ملف الحزمة المضغوط (Local AI أو Mature) في مجلد Cyberpunk 2077، أي المجلد الذي يحتوي على bin وarchive وr6، وليس في مجلد جديد باسم الملف المضغوط. يجب أن توضع ملفاتها في red4ext/plugins/AiNpcCyberpunkMod/app/local-ai.",
    ["Not your conversation provider. Choose it on the AI provider page."] = "هذا ليس مزود المحادثات المختار. اختره من صفحة مزود الذكاء الاصطناعي.",
    ["Open this page to restore its defaults."] = "افتح هذه الصفحة لاستعادة إعداداتها الافتراضية.",
    ["Requires a Mistral key (add the Voxtral key in Voice AI and microphone)"] = "يتطلب مفتاح Mistral (أضف مفتاح Voxtral في الصوت بالذكاء الاصطناعي والميكروفون)",
    ["Requires an Inworld key (add the Inworld API key in Voice AI and microphone)"] = "يتطلب مفتاح Inworld (أضف مفتاح Inworld API في الصوت بالذكاء الاصطناعي والميكروفون)",
    ["Speaking to companions needs Convai for now. Set the provider to Convai free tier on the AI provider page, or type your message."] = "التحدث مع المرافقين يحتاج Convai حاليا. اضبط المزود على المستوى المجاني من Convai في صفحة مزود الذكاء الاصطناعي، أو اكتب رسالتك.",
    ["The AMD setup (Voice AI and microphone > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "يشغل إعداد AMD (الصوت بالذكاء الاصطناعي والميكروفون > OmniVoice for AMD) نموذج OmniVoice مع ROCm على {card}. تجريبي.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Voice AI and microphone > OmniVoice for AMD. Until then Pocket speaks."] = "لم يستخدم إعداد AMD: {reason}. اختر إعادة التثبيت في الصوت بالذكاء الاصطناعي والميكروفون > OmniVoice for AMD. حتى ذلك الحين يتحدث Pocket.",
    ["The Local AI pack zip {name} has not been extracted. Extract it into your Cyberpunk 2077 folder, the one with bin, archive and r6, and not into a new folder named after the zip."] = "لم يفك ضغط ملف الحزمة المضغوط {name} الخاص بـ Local AI بعد. فك ضغطه في مجلد Cyberpunk 2077، أي المجلد الذي يحتوي على bin وarchive وr6، وليس في مجلد جديد باسم الملف المضغوط.",
    ["The OmniVoice pack zip {name} has not been extracted. Extract it into your Cyberpunk 2077 folder, the one with bin, archive and r6, and not into a new folder named after the zip. Then restart the game."] = "لم يفك ضغط ملف الحزمة المضغوط {name} الخاص بـ OmniVoice بعد. فك ضغطه في مجلد Cyberpunk 2077، أي المجلد الذي يحتوي على bin وarchive وr6، وليس في مجلد جديد باسم الملف المضغوط. ثم أعد تشغيل اللعبة.",
    ["OmniVoice is chosen but its pack is not found, so replies show as text. Extract the OmniVoice pack zip into your Cyberpunk 2077 folder, the one with bin, archive and r6. Its files belong in red4ext/plugins/AiNpcCyberpunkMod/app/omni. Then restart the game."] = "تم اختيار OmniVoice لكن لم يعثر على حزمته، لذلك تظهر الردود كنص. فك ضغط ملف حزمة OmniVoice المضغوط في مجلد Cyberpunk 2077، أي المجلد الذي يحتوي على bin وarchive وr6. يجب أن توضع ملفاتها في red4ext/plugins/AiNpcCyberpunkMod/app/omni. ثم أعد تشغيل اللعبة.",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini on the AI provider page."] = "تم الوصول إلى حد المحادثات. حاول لاحقا، أو اختر Local AI أو Google Gemini من صفحة مزود الذكاء الاصطناعي.",
    ["The custom provider did not accept your key. Check it on the AI provider page."] = "لم يقبل المزود المخصص مفتاحك. تحقق منه في صفحة مزود الذكاء الاصطناعي.",
    ["The custom provider did not answer. Check its address on the AI provider page, or try again."] = "لم يستجب المزود المخصص. تحقق من عنوانه في صفحة مزود الذكاء الاصطناعي، أو حاول مرة أخرى.",
    ["The custom provider does not know that model ID. Check it on the AI provider page."] = "لا يعرف المزود المخصص معرف النموذج هذا. تحقق منه في صفحة مزود الذكاء الاصطناعي.",
    ["The game did not name anyone. Face the character, then choose Character editor on the Companion Manager menu again."] = "لم تسم اللعبة أحدا. واجه الشخصية، ثم اختر محرر الشخصيات من قائمة مدير المرافقين مجددا.",
    ["This model only thinks. Choose a non-reasoning model in AI provider."] = "هذا النموذج يفكر فقط. اختر نموذجا لا يعتمد على الاستدلال من مزود الذكاء الاصطناعي.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Voice AI and microphone > OmniVoice for AMD: one download, then it starts by itself."] = "بطاقتك AMD Radeon ({card}) قادرة على تشغيل OmniVoice. اضبطها في الصوت بالذكاء الاصطناعي والميكروفون > OmniVoice for AMD: تنزيل واحد، ثم تبدأ وحدها تلقائيا.",
    ["Your AMD Radeon card can run OmniVoice. Set it up on Voice AI and microphone > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "بطاقتك AMD Radeon قادرة على تشغيل OmniVoice. اضبطها في الصوت بالذكاء الاصطناعي والميكروفون > OmniVoice for AMD: تنزيل واحد، ثم تبدأ وحدها تلقائيا. حتى ذلك الحين يتحدث Pocket.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key on the AI provider page."] = "وصل مفتاح Convai API الخاص بك إلى حد خطته. حاول لاحقا، أو أضف مفتاحا آخر في صفحة مزود الذكاء الاصطناعي.",
    ["Your Convai plan is active. Choose Convai API key on the AI provider page."] = "خطة Convai الخاصة بك مفعلة. اختر مفتاح Convai API من صفحة مزود الذكاء الاصطناعي.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider on the AI provider page. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "وصلت إلى حد المستوى المجاني من Convai لهذا اليوم. يعاد ضبطه في {time}. لمواصلة الحديث الآن، اختر مزودا آخر من صفحة مزود الذكاء الاصطناعي. Local AI غير محدود ويعمل على جهازك. يعمل Google Gemini بمفتاحك الخاص.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Voice AI and microphone > Microphone."] = "يبدو أن {name} ينقل صوت الكمبيوتر، مثل مكالمة، وليس صوتك وحده. اختر ميكروفونك الحقيقي من الصوت بالذكاء الاصطناعي والميكروفون > الميكروفون.",
    ["{name}, chosen in Voice AI and microphone."] = "{name}، مختار في الصوت بالذكاء الاصطناعي والميكروفون.",
    ["{name}, the Windows default input. Voice AI and microphone > Microphone chooses another."] = "{name}، جهاز الإدخال الافتراضي في Windows. اختر جهازا آخر من الصوت بالذكاء الاصطناعي والميكروفون > الميكروفون.",
    ["Automatic follows the “Companions change outfits” setting: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your party’s companions and residents are dressed, including allies another mod spawned (they get their own clothes back when they leave), and they change while nobody is looking. Characters the game places are never changed."] = "الوضع التلقائي يتبع إعداد «يغير الرفاق ملابسهم»: إطلالة في النهار وأخرى في الليل، وتغيير من حين لآخر، وملابس مريحة في المنزل. الإطلالة التي تختارها تلبس طوال الوقت. لا يلبس إلا رفاق مجموعتك والمقيمون، ومنهم الحلفاء الذين أنشأهم تعديل آخر (يستعيدون ملابسهم عند المغادرة)، ويغيرون ملابسهم حين لا يراهم أحد. الشخصيات التي تضعها اللعبة لا تتغير ملابسها أبدا.",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s copies and spawned allies, never the game’s own characters. Turning this off keeps what they wear now."] = "يغير رفاق مجموعتك ملابسهم من حين لآخر: إطلالة في النهار وأخرى في الليل، وملابس مريحة في المنزل، حين تتوفر لدى الشخصية.\n\nيحدث ذلك بعيدا عن نظرك فقط، ولا يحدث أمامك أبدا، ولنسخ مجموعتك والحلفاء المنشئين فقط، ولا يشمل شخصيات اللعبة نفسها. إيقاف هذا الإعداد يبقي ما يرتدونه الآن.",
    ["The language the characters speak. Counts only while Companion voices is not Off. With it Off, replies follow what you write.\n\nAutomatic: follows what you write. With Mistral you can mix languages by voice.\n\nLanguages after Arabic need Mistral, Gemini, Custom or Local AI to write them, and a voice that speaks them: OmniVoice all, Voxtral most, Pocket English only (shows text). Not with Convai."] = "اللغة التي تتحدث بها الشخصيات. تطبق هذه اللغة فقط ما دامت أصوات الرفاق غير متوقفة. وعند إيقافها تتبع الردود ما تكتبه.\n\nتلقائي: يتبع ما تكتبه. مع Mistral يمكنك المزج بين اللغات بالصوت.\n\nاللغات التي تأتي بعد العربية تحتاج إلى Mistral أو Gemini أو مخصص أو Local AI لكتابتها، وإلى صوت يتحدثها: OmniVoice كل اللغات، و Voxtral معظمها، و Pocket الإنجليزية فقط (يعرض النص). غير متاح مع Convai.",
    ["Group chat keeps going"] = "استمرار الدردشة الجماعية",
    ["A few lines"] = "بضعة أسطر",
    ["Longer"] = "أطول",
    ["After a group chat you started, your companions in it keep talking to each other for a few more lines, answering one another, then wait for you. Anything you do ends it at once. Never during fights, scenes, calls or menus.\n\nA few lines: about 3. Longer: about 5. Each line is one conversation turn and counts toward the limits of your provider."] = "بعد دردشة جماعية بدأتها، يواصل رفاقك المشاركون فيها الحديث فيما بينهم بضعة أسطر أخرى، يرد كل منهم على الآخر، ثم ينتظرونك. أي شيء تفعله ينهيها فورا. لا يحدث ذلك أبدا أثناء القتال أو المشاهد أو المكالمات أو القوائم.\n\nبضعة أسطر: نحو 3. أطول: نحو 5. كل سطر يمثل دورا واحدا في المحادثة ويحتسب ضمن حدود مزودك.",
    ["Choose how long a group chat keeps going."] = "اختر مدة استمرار الدردشة الجماعية.",
    ["V’s language"] = "لغة V",
    ["Same as companions"] = "مثل الرفاق",
    ["As typed"] = "كما كتبت",
    ["The language V speaks, apart from the companions.\n\nSame as companions: one language for everyone. As typed: V says exactly what you typed, with no translation.\n\nA language: V says your line translated into it, and the companions still get what you typed. Needs an AI provider that can translate (Gemini, Mistral, Local AI, Custom, or a Gemini or Mistral key with Convai) and a voice that speaks it."] = "اللغة التي يتحدث بها V بمعزل عن الرفاق.\n\nمثل الرفاق: لغة واحدة للجميع. كما كتبت: يقول V ما كتبته بالضبط دون ترجمة.\n\nلغة محددة: يقول V سطرك مترجما إليها ويظل الرفاق يستلمون ما كتبته. يتطلب مزود ذكاء اصطناعي يستطيع الترجمة (Gemini أو Mistral أو Local AI أو Custom أو مفتاح Gemini أو Mistral مع Convai) وصوتا ينطقها.",
    ["Choose one of the listed languages for V."] = "اختر إحدى اللغات المدرجة لـ V.",
    ["V says your line as you typed it: Convai cannot translate, and no Google Gemini or Mistral key is saved."] = "يقول V سطرك كما كتبته: لا يستطيع Convai الترجمة، ولا يوجد مفتاح Google Gemini أو Mistral محفوظ.",
    ["V says your line as you typed it: Pocket speaks English only. Choose OmniVoice or Voxtral as V’s voice engine."] = "يقول V سطرك كما كتبته: Pocket ينطق الإنجليزية فقط. اختر OmniVoice أو Voxtral كمحرك صوت V.",
    ["OmniVoice is not running, so other languages show as text. See Help and support."] = "OmniVoice غير قيد التشغيل، لذا تظهر اللغات الأخرى كنص. انظر المساعدة والدعم.",
    ["Remote OmniVoice has no server address. Add one in Custom voices or turn it off."] = "OmniVoice عن بعد ليس له عنوان خادم. أضف عنوانا في أصوات مخصصة أو أوقفه.",
    ["The OmniVoice pack is not found, so other languages show as text. See Help and support."] = "حزمة OmniVoice غير موجودة، لذا تظهر اللغات الأخرى كنص. انظر المساعدة والدعم.",
    ["OmniVoice did not start, so replies in other languages show as text. Restart the game. If it happens again, save a report below and share it on the mod’s Discord."] = "لم يبدأ OmniVoice، لذا تظهر الردود بلغات أخرى كنص. أعد تشغيل اللعبة. إن تكرر ذلك، فاحفظ تقريرا أدناه وشاركه على Discord الخاص بالمود.",
    ["Not added: {reason}"] = "غير مضاف: {reason}",
    ["clipboard could not be read"] = "تعذر قراءة الحافظة",
    ["could not be saved"] = "تعذر الحفظ",
    ["clipboard empty"] = "الحافظة فارغة",
    ["not a web address"] = "ليس عنوان ويب",
    ["must start with https:// or http://"] = "يجب أن يبدأ ب https:// أو http://",
    ["https:// needed here"] = "https:// مطلوب هنا",
    ["base URL only"] = "عنوان URL الأساسي فقط",
    ["too long"] = "طويل جدا",
    ["not an API key"] = "ليس مفتاح API",
    ["not a model ID"] = "ليس معرف نموذج",
    ["not accepted"] = "لم يتم القبول",
    ["If pasting does not work on your system (Linux with Proton, for example), write endpoint=, model= and api-key= lines in player-custom-endpoint.txt in the conversation service data folder instead (AppData/Local/AiNpcCyberpunkMod/data inside the game prefix), then press Test connection."] = "إذا لم يعمل اللصق على نظامك (مثل Linux مع Proton)، فاكتب بدلا من ذلك أسطر endpoint= وmodel= وapi-key= في الملف player-custom-endpoint.txt داخل مجلد بيانات خدمة المحادثة (AppData/Local/AiNpcCyberpunkMod/data داخل بادئة اللعبة)، ثم اضغط اختبار الاتصال.",
    ["Show"] = "عرض",
    ["Show: {what}"] = "عرض: {what}",
    ["All models"] = "كل النماذج",
    ["Fights"] = "يقاتل",
    ["All models, or only the models whose copy fights when combat starts. Children and bodies of unknown age never fight."] = "كل النماذج، أو فقط النماذج التي تقاتل نسختها عندما يبدأ القتال. الأطفال والأجسام مجهولة العمر لا يقاتلون أبدًا.",

-- Community conversation-extension interface strings. Existing upstream translations above retain priority.
    ["Shorter replies"] = "ردود أقصر",
    ["Natural replies"] = "ردود طبيعية",
    ["Longer replies"] = "ردود أطول",
    ["Choose one of the listed reply lengths."] = "اختر أحد أطوال الردود المدرجة.",
    ["Rarely (2/hour)"] = "نادرًا (2/ساعة)",
    ["Normally (4/hour)"] = "عادةً (4/ساعة)",
    ["Often (6/hour)"] = "كثيرًا (6/ساعة)",
    ["Frequent (30/hour)"] = "متكرر (30/ساعة)",
    ["Often (30/hour)"] = "كثيرًا (30/ساعة)",
    ["Very often (60/hour)"] = "كثيرًا جدًا (60/ساعة)",
    ["Scene chatter (may overlap game dialogue)"] = "أحاديث المشاهد (قد تتداخل مع حوار اللعبة)",
    ["Conversation status HUD"] = "عرض حالة المحادثة",
    ["Show conversation service, listening, reply, subtitles and audio status at the top left during play."] = "يعرض حالة الخدمة والاستماع والرد والترجمة والصوت أعلى اليسار أثناء اللعب.",
    ["Choose shorter, natural or longer replies for conversations and calls with text providers. Natural Japanese replies usually use two to four sentences. Automatic remarks and combat lines keep their own pacing."] = "اختر ردودًا أقصر أو طبيعية أو أطول للمحادثات والمكالمات مع مزودي النص. تتكون الردود اليابانية الطبيعية عادةً من جملتين إلى أربع جمل. تحتفظ التعليقات التلقائية وعبارات القتال بإيقاعها الخاص.",
    ["Johnny answers while the story places him in V’s head. Bind Talk to Johnny on Key bindings. On means answers only. Other choices target 2, 4, 6, 30 or 60 automatic remarks per eligible hour. Johnny and companions take turns. Scene chatter may overlap game dialogue. Choices, calls, fights and menus block automatic remarks."] = "يرد جوني عندما تضعه القصة داخل رأس V. عيّن أمر التحدث إلى جوني في إعدادات المفاتيح. خيار التشغيل يتيح الردود فقط. تستهدف الخيارات الأخرى 2 أو 4 أو 6 أو 30 أو 60 تعليقًا تلقائيًا لكل ساعة تتوفر فيها الظروف المناسبة. يتناوب جوني والرفاق على الكلام. قد تتداخل أحاديث المشاهد مع حوار اللعبة. تمنع الخيارات والمكالمات والقتال والقوائم التعليقات التلقائية.",
    ["Nearby companions can start conversations with up to three speakers. Join by talking. Targets are 2, 4, 30 or 60 per eligible hour. Fights, calls, choices and menus block automatic starts. Scene chatter also permits scenes and vehicle travel and may overlap game dialogue. Housemates keep their separate pause setting."] = "يمكن للرفاق القريبين بدء محادثات تضم حتى ثلاثة متحدثين. انضم بالتحدث. الهدف هو 2 أو 4 أو 30 أو 60 بداية محادثة لكل ساعة تتوفر فيها الظروف المناسبة. يمنع القتال والمكالمات والخيارات والقوائم البدء التلقائي. تسمح أحاديث المشاهد بالكلام أثناء المشاهد والتنقل بالمركبات أيضًا، وقد تتداخل مع حوار اللعبة. يحتفظ رفاق السكن بإعداد التوقف المنفصل.",
    ["Allows automatic companion and Johnny conversations during eligible scenes and vehicle travel. Speech may overlap game dialogue. Choices, calls, fights, menus and braindances still block automatic speech. Manual conversation follows the base mod."] = "يسمح بالمحادثات التلقائية للرفاق وجوني أثناء المشاهد المناسبة والتنقل بالمركبات. قد يتداخل الكلام مع حوار اللعبة. تظل الخيارات والمكالمات والقتال والقوائم والبريندانس مانعةً للكلام التلقائي. تتبع المحادثات اليدوية قواعد التعديل الأساسي.",
